function LaunchScreen() {
  const { screenRef } = useScreenPortal();
  const [target, setTarget] = useState<HTMLDivElement | null>(null);
  const [visible, setVisible] = useState(true);
  useEffect(() => {
    setTarget(screenRef.current);
    const t = window.setTimeout(() => setVisible(false), 1100);
    return () => window.clearTimeout(t);
  }, [screenRef]);
  if (!visible || !target) return null;
  return createPortal(
    <div
      className="crays-launch"
      role="status"
      aria-label="CRAYS is loading"
      data-testid="crays-launch"
    >
      <div className="crays-launch-brand">
        <img src={asset("wordmark-white-original.svg")} alt="CRAYS" />
        <p>Work . Live . Play</p>
      </div>
    </div>,
    target,
  );
}

