function PersonalRouteAccess({route,header=false,children}:{route:PersonalNavigationRoute;header?:boolean;children:ReactNode}){
 const runtime=useWebChuck();const {state}=useStore(),w=state.world;let allowed=!(isLibraryNavigationName(route.name)||['requests','people','sentRequests','libraryMedia','ownContent','wave','learning','books','householdBudget','apps','permissions','permission','delegations','memory','manualTask','spotPaymentRecords'].includes(route.name))||ownPrivateAccount(w);
 if(route.id){
  const originals=w.objects.filter(o=>o.id===route.id);
  if(route.name==='spot'||route.name==='spotPhotos'||route.name==='spotHours'||route.name==='spotRules'||route.name==='spotVisit'||route.name==='spotDirections'||route.name==='spotContact')allowed=w.venues.filter(v=>v.id===route.id).length===1;
  else if(route.name==='spotAccess')allowed=ownPrivateAccount(w)&&w.venues.filter(v=>v.id===route.id).length===1;
  else if(route.name==='publishedLocationHours')allowed=route.id===publishedGymHoursId;
  else if(route.name==='spotCommunityFeed')allowed=ownPrivateAccount(w)&&w.venues.filter(v=>v.id===route.id).length===1&&spaceCommunityAllowed(w,route.id);
  else if(route.name==='spotBookings')allowed=ownPrivateAccount(w)&&w.venues.filter(v=>v.id===route.id).length===1;
  else if(route.name==='waveConversation')allowed=ownPrivateAccount(w)&&waveInvitations(w).filter(i=>i.id===route.id).length===1;
  else if(route.name==='conversation'){try{allowed=!!runtime&&route.id==='chuck'||ownPrivateAccount(w)&&exactConversation(w,route.id).canRead;}catch{allowed=false;}}
  else if(route.name==='contentRights'){const posts=w.posts.filter(p=>p.id===route.id);allowed=ownPrivateAccount(w)&&posts.length===1&&mayRead(w,posts[0]);}
  else if(route.name==='agentTask')allowed=runtime&&/^personal-task-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(route.id)?true:ownPrivateAccount(w)&&originals.length===1&&originals[0].owner===w.owner&&originals[0].kind==='agent-task';
  else if(route.name==='permission'){try{allowed=ownPrivateAccount(w)&&!!ownPrivacyRecord(w,route.id);}catch{allowed=false;}}
  else if(route.name==='manualTask')allowed=ownPrivateAccount(w)&&!!manualTaskFor(w,route.id);
  else if(route.name==='task')allowed=ownPrivateAccount(w)&&state.tasks.filter(t=>t.id===route.id).length===1;
  else if(route.name==='plan')allowed=ownPrivateAccount(w)&&originals.length===1&&originals[0].owner===w.owner&&(['booking','reservation','event','order','meeting','personal-plan'].includes(String(originals[0].kind))||originals[0].webPersonalPlan===true);
  else if(route.name==='event')allowed=ownPrivateAccount(w)&&originals.length===1&&originals[0].owner===w.owner&&originals[0].kind==='event';
  else if(route.name==='community')allowed=ownPrivateAccount(w)&&originals.length===1&&originals[0].owner===w.owner&&originals[0].kind==='group'&&circleDiscoverableGroups(w).filter(o=>o.id===route.id).length===1;
  else if(route.name==='communityProgramme')allowed=communityProgramme(w,route.id).status==='ready';
  else if(route.name==='ticketOrder')allowed=!!ticketOrder(w,route.id);
  else if(route.name==='membership'||route.name==='membershipDocuments')allowed=!!communityMembership(w,route.id);
 }
 if(!allowed&&route.name==='communityProgramme'&&route.id&&ownPrivateAccount(w)&&w.settings['community-calendar-follow:'+route.id]==='Yes')return header?null:<UnavailableFollowedProgramme groupId={route.id}/>;
 if(!allowed&&route.name==='spotPaymentRecords')return header?null:<WebSpotPaymentRecordsEntry venueId={route.id||''}/>;
 if(!allowed)return header?null:<PersonalRouteUnavailable route={route}/>;
 return <>{children}</>;
}
/** A denied original has a safe way out, without exposing a private parent record. */
