function openNotesTask(flow:ReturnType<typeof useFlow>,world:ProductWorld,taskId:string){const task=world.objects.find(o=>o.owner===world.owner&&o.id===taskId&&o.kind==='agent-task'&&o.capabilityId==='B2C-CAP-008');if(!task)return;const result=world.objects.find(o=>o.owner===world.owner&&o.id===task.resultId);flow.push(result?.kind==='personal-note'?((conversationFor(world,result.id)||result.sourceRef)?conversationNotesScreen(result.id):personalNotesScreen(result.id)):result?.kind==='personal-note-search'?personalNotesScreen('','','','',false,result.id):personalNotesScreen('',task.id,String(task.request||''),`task:${task.id}`));}
const conversationNotesScreen=(noteId="",bridgeScope="")=>screen(`conversation-notes-${bridgeScope||noteId||"all"}`,"Notes with Chuck",()=> <ConversationNotesEntry noteId={noteId} bridgeScope={bridgeScope}/>);
function ConversationNotesEntry({noteId,bridgeScope=""}:{noteId:string;bridgeScope?:string}){
 const {world,run,update}=useProduct(),flow=useFlow(),{setState,getState}=useStore();
 const key=bridgeScope?`voice-conversation:${bridgeScope}`:`conversation-notes:${noteId||"new"}`;
 const {draft,set:unboundSet}=useFeatureDraft(key,{value:""});let parsedSourceRef:PrivateSourceRef|undefined;
 try{if(bridgeScope)parsedSourceRef=JSON.parse(draft.sourceRef||'null')||undefined;}catch{}
 const sourceRef=parsedSourceRef;
 const bridgeCurrent=(w:ProductWorld)=>{if(w.owner!==world.owner||!w.identity.signedIn)return false;if(!bridgeScope)return true;const exact=w.drafts[`${w.owner}:${key}`];if(!exact||exact.owner!==w.owner||exact.noteId!==noteId||!sourceRef||JSON.stringify(sourceRef)!==exact.sourceRef||!privateSourceCurrent(w,sourceRef))return false;const n=noteId?rawPersonalNote(w,noteId):undefined;return !noteId||!!n&&String(n.version)===exact.expectedVersion;};
 const set=(name:string,value:string)=>{if(!bridgeScope){unboundSet(name,value);return;}if(name!=='value')return;update(w=>!bridgeCurrent(w)?w:{...w,drafts:{...w.drafts,[`${w.owner}:${key}`]:{...w.drafts[`${w.owner}:${key}`],value}}});};
 const guardedRun=(op:string,data:Record<string,string>,ctx:ActionContext):ActionResult=>{const w=getState().world;if(!bridgeCurrent(w))return {world:w,ok:false,objectId:noteId,message:'The exact source or original note version changed. Review the same voice original again.'};return run(op,data,ctx);};
 if(bridgeScope&&(!sourceRef||!bridgeCurrent(world)))return <MobileScroll><section className="detail-content"><h1>Your original needs review.</h1><p>The voice source, access or target note version changed. No cached words are shown.</p>{sourceRef?.kind==='private-voice-transcript'&&<button className="secondary" onClick={()=>{const w=getState().world;if(w.owner===world.owner&&voiceFor(w,sourceRef.voiceId))flow.push(privateVoiceScreen('B2C-CAP-071',sourceRef.voiceId));}}>Review the same voice original</button>}<button className="quiet" onClick={()=>flow.push(libraryWorkspaceScreen('libraryConversationNotes'))}>My conversations</button></section></MobileScroll>;
 const heldNote=noteId?rawPersonalNote(world,noteId):undefined;
 if(!bridgeScope&&heldNote?.sourceRef&&!noteFor(world,noteId)){const ref=heldNote.sourceRef;return <MobileScroll><section className="detail-content"><h1>Your original needs review.</h1><p>The original source changed or its access was revoked. Cached transcript and summary words stay hidden.</p>{ref.kind==='private-voice-transcript'&&<button className="secondary" onClick={()=>{const w=getState().world;if(w.owner===world.owner&&w.identity.signedIn&&voiceFor(w,ref.voiceId))flow.push(privateVoiceScreen('B2C-CAP-071',ref.voiceId));}}>Review the same voice original</button>}<button className="quiet" onClick={()=>flow.push(libraryWorkspaceScreen('libraryConversationNotes'))}>My conversations</button></section></MobileScroll>;}
 return <ConversationNotesWorkspace key={`${world.owner}:${noteId}:${bridgeScope}`} world={world} noteId={noteId} sourceRef={sourceRef} draft={draft} set={set} run={guardedRun} onVoiceOriginal={id=>{const w=getState().world;if(w.owner===world.owner&&w.identity.signedIn&&voiceFor(w,id))flow.push(privateVoiceScreen('B2C-CAP-071',id));}} onOpen={id=>flow.push(conversationNotesScreen(id))} onOriginal={id=>flow.push(personalNotesScreen(id))} onChecklist={id=>flow.push(personalChecklistScreen(id))} onAppointment={id=>flow.push(appointmentPlannerScreen(id))} onPerson={id=>flow.push(id==="alex"?chatScreen("alex"):controlScreen("private-person-chat",{personId:id}))} onChuck={(question,refs)=>{const allowed=(w:ProductWorld)=>w.owner===world.owner&&w.identity.signedIn&&refs.every(ref=>{const n=noteFor(w,ref.noteId);return !!n&&!n.sourceRef;});if(!allowed(getState().world))return false;try{conversationChuckDraft(getState().world,question,refs);}catch{return false;}let accepted=false;setState(state=>{if(!allowed(state.world))return state;let text:string;try{text=conversationChuckDraft(state.world,question,refs);}catch{return state;}accepted=true;return {...state,drafts:{...state.drafts,chuck:text},context:{...state.context,chuck:{featureId:"AL-277",sourceId:refs[0].noteId}}};});if(accepted)flow.push(chatScreen("chuck"));return accepted;}}/>;
}
