        {capabilityId==="B2C-CAP-013"&&<button className="secondary" onClick={()=>flow.push(readingScreen("digest","","",draft.request,`brief:${draft.request}`))}><Newspaper size={21}/> Catch up on my topics</button>}
        {capabilityId==="B2C-CAP-012"&&<button className="secondary" onClick={()=>flow.push(sourceComparisonScreen("","",draft.request,`brief:${draft.request}`))}><MagnifyingGlass size={21}/> Compare my sources</button>}
