        {capabilityId==="B2C-CAP-010"&&<button className="secondary" onClick={()=>flow.push(personalDeadlineScreen("","",draft.request,`brief:${draft.request}`))}><CalendarBlank size={21}/> Plan my deadline</button>}
        {capabilityId==="B2C-CAP-009"&&<button className="secondary" onClick={()=>flow.push(privateDocumentsScreen("","",draft.request,`brief:${draft.request}`))}><FileText size={21}/> Choose my private documents</button>}
        {capabilityId==="B2C-CAP-008"&&<button className="secondary" onClick={()=>flow.push(personalNotesScreen("","",draft.request,`brief:${draft.request}`))}><NotePencil size={21}/> Open my notes</button>}
        {capabilityId==="B2C-CAP-007"&&<button className="secondary" onClick={()=>flow.push(personalHabitScreen("","",draft.request,`brief:${draft.request}`))}><CalendarBlank size={21}/> Build my routine</button>}
