function WaveEntry(){const flow=useFlow();return <button type="button" className="wave-entry" onClick={()=>flow.push(waveScreen())}><span className="wave-entry-symbol" aria-hidden="true"><HandWaving size={25}/></span><span className="wave-entry-copy"><strong>Wave Nearby</strong><small>Voluntary nearby discovery · preview</small></span><CaretRight size={19} aria-hidden="true"/></button>;}
