function SavedReadingWorkspace({kind}:{kind:ReadingKind}){const {world}=useProduct();const flow=useFlow();if(!world.identity.signedIn)return <MobileScroll><div className="detail-content"><h1>Your reading workspace is private.</h1><p>Sign in to open your own originals and drafts.</p></div></MobileScroll>;const records=kind==='pdf'?pdfQuestionsFor(world,{includeArchived:true}):kind==='article'?articlesFor(world,{includeArchived:true}):digestsFor(world,{includeArchived:true});const prefix=`${kind==='pdf'?'crays-pdf-questions-v1':kind==='article'?'crays-article-explanation-v1':'crays-personal-news-digest-v1'}:${world.owner}:`;const drafts:{name:string;scope:string}[]=[];try{for(let index=0;index<localStorage.length;index++){const key=localStorage.key(index)||"";if(!key.startsWith(prefix)||key.endsWith(":recovery"))continue;const local=JSON.parse(localStorage.getItem(key)||"null");if(!local||local.id||typeof local.draft?.name!=="string"||!local.draft.name.trim())continue;drafts.push({name:local.draft.name,scope:key.slice(prefix.length)});}}catch{}return <MobileScroll><div className="detail-content"><h1>{kind==='pdf'?'Your PDF questions':kind==='article'?'Your article explanations':'Your news digests'}</h1><p>Your private originals and their source reviews.</p><button className="primary" onClick={()=>flow.push(readingScreen(kind))}>Start with Chuck</button>{drafts.length>0&&<h2>Pick up where you left off</h2>}{drafts.map(draft=><button className="chat-row" aria-label={draft.name} key={draft.scope} onClick={()=>{const task=world.objects.find(o=>o.owner===world.owner&&o.kind==="agent-task"&&o.id===draft.scope);flow.push(readingScreen(kind,"",task?.id||"","",task?"":draft.scope));}}><NotePencil size={24}/><span><strong>{draft.name}</strong><small>Unfinished draft · review before saving</small></span><CaretRight size={19}/></button>)}{records.length>0&&<h2>Your saved originals</h2>}{records.map(record=><button className="chat-row" aria-label={record.name} key={record.id} onClick={()=>flow.push(readingScreen(kind,record.id))}><BookOpen size={24}/><span><strong>{record.name}</strong><small>{record.status}</small></span><CaretRight size={19}/></button>)}</div></MobileScroll>;}

function Collection({ kind }: { kind: string }) {
  if (kind === "explore") return <ExploreRoot />;
  if (kind === "places")
    return (
      <MobileScroll>
        <div className="detail-content root-spaces">
          <PlacesList />
        </div>
      </MobileScroll>
    );
  if (kind === "activity") return <WebActivityRootEntry />;
  if (kind === "network") return <NetworkExperience />;
  if (kind === "services")
    return <OrderingPanel featureId="AL-141" context={{}} />;
  return <PersonalSpace />;
}

const venueHoursScreen=(venueId:string):FlowScreen=>{
 const route=readPersonalNavigationRoute({name:venueId===publishedGymHoursId?'publishedLocationHours':'spotHours',id:venueId});
 if(!route)return screen(`venue-hours-${venueId}`,"Opening hours",()=> <VenueHoursEntry venueId={venueId}/>);
 const original={...screen(`venue-hours-${venueId}`,"Opening hours",()=> <VenueHoursEntry venueId={venueId} desktop/>),header:undefined,headerHeight:0,webRoute:route};
 return {...original,render:flow=><PersonalRouteAccess route={route}>{original.render(flow)}</PersonalRouteAccess>};
};
function VenueHoursEntry({venueId,desktop=false}:{venueId:string;desktop?:boolean}){
 const {world,run}=useProduct();const flow=useFlow();const reference=venueId===publishedGymHoursId;
 const parent:PersonalNavigationRoute=reference?{name:'memberships'}:{name:'spot',id:venueId};
 const list:PersonalNavigationRoute=reference?{name:'memberships'}:{name:'personalSpots'};
 const name=reference?'CRAYS Gym · Sankt Augustin':world.venues.filter(v=>v.id===venueId).length===1?world.venues.find(v=>v.id===venueId)!.name:'Spot';
 const chrome=desktop?{back:()=>flow.pop(),breadcrumbs:<><WebContextLink route={list} onOpen={()=>flow.push(resolvePersonalScreen(list))}>{reference?'Memberships & passes':'Your Spots'}</WebContextLink><span aria-hidden="true">/</span>{!reference&&<><WebContextLink route={parent} onOpen={()=>flow.push(resolvePersonalScreen(parent))}>{name}</WebContextLink><span aria-hidden="true">/</span></>}<span>{reference?name+' · Opening hours':'Opening hours'}</span></>,returnLink:<WebContextLink route={parent} onOpen={()=>flow.push(resolvePersonalScreen(parent))}>{reference?'Return to memberships & passes':'Return to Spot'} <CaretRight size={18}/></WebContextLink>}:undefined;
 return <VenueHoursWorkspace key={`${world.owner}:${venueId}`} desktop={chrome} world={world} venueId={venueId} run={run} asset={asset} onContact={()=>flow.push(controlScreen("venue-contact",{venueId}))}/>;
}
