 const pairing=world.identity.signedIn&&ownTask&&(!resultId||!!original)&&(!taskId||(!task.resultId||task.resultId===original?.id)&&(!original||original.sourceTaskId===taskId));if(!pairing)return <MobileScroll><section className="detail-content"><h1>This exact link check needs review.</h1><p>No foreign or mismatched result is replaced by an editable blank task.</p><button onClick={()=>flow.pop()}>Back</button></section></MobileScroll>;
