function HousingWatchEntry({resultId,taskId,request,draftScope}:{resultId:string;taskId:string;request:string;draftScope:string}){
 const {world,run}=useProduct(),{getState}=useStore(),flow=useFlow(),original=resultId?housingFor(world,resultId):undefined;
 const {draft,set}=useFeatureDraft(`housing-watch:${resultId||taskId||draftScope}`,{view:''});let view:HousingView={...emptyHousingView(world.owner),...(original?{draft:structuredClone(original.draft)}:{})};
 if(!original&&request)view.draft.request=request;
 try{const saved=JSON.parse(draft.view);if(saved?.owner===world.owner&&saved.draft?.criteria&&Array.isArray(saved.draft.sources)&&typeof saved.query==='string'&&typeof saved.selectedSourceId==='string'&&typeof saved.selectedListingId==='string')view={...view,...saved};}catch{}
 const tasks=taskId?world.objects.filter(o=>o.id===taskId):[];
 if(resultId&&(!original||taskId&&original.sourceTaskId!==taskId)||taskId&&(tasks.length!==1||tasks[0].owner!==world.owner||tasks[0].kind!=='agent-task'||tasks[0].capabilityId!==housingCapability))return <MobileScroll><section className="detail-content"><Info error>This exact own housing search or task pairing is unavailable. No other source result is substituted.</Info><button className="secondary" onClick={()=>flow.pop()}>Back</button></section></MobileScroll>;
 if(tasks[0]&&!prototypeTaskSourceCurrent(world,tasks[0]))return <PrivateTaskSourceHold taskId={tasks[0].id}/>;
 return <HousingWatchWorkspace key={`${world.owner}:${resultId}:${taskId}:${draftScope}`} world={world} getWorld={()=>getState().world} run={run} resultId={resultId} taskId={taskId} request={request} viewState={view} onViewStateChange={next=>{if(next.owner===world.owner)set('view',JSON.stringify(next));}} onSaved={id=>{if(id===resultId)return;const current=getState().world,r=housingFor(current,id);if(current.owner===world.owner&&r&&(!taskId||r.sourceTaskId===taskId))flow.replace(housingWatchScreen(r.id,r.sourceTaskId,request));}} onTask={id=>{const current=getState().world,rows=current.objects.filter(o=>o.id===id);if(current.owner===world.owner&&rows.length===1&&rows[0].owner===current.owner&&rows[0].kind==='agent-task'&&rows[0].capabilityId===housingCapability)flow.push(featureScreen('AL-293',{objectId:id}));}} onResearchSource={(researchId,sourceId)=>{const current=getState().world,r=housingFor(current,resultId),source=r?.draft.sources.find(s=>s.kind==='research'&&s.research?.researchId===researchId&&s.research.sourceId===sourceId);if(current.owner===world.owner&&r&&source&&housingSourceState(current,r,source).ready)flow.push(housingResearchSourceScreen(r.id,source.id));}} onBack={()=>flow.pop()}/>;
}
