const additionalCapabilities:readonly string[]=[restaurantCapability,meshCapability,documentImportCapability,chessCapability,communityQueryCapability,contactBoundaryCapability,...recommendationCapabilities];
function additionalCapabilityTitle(cap:string){return cap===restaurantCapability?'restaurant booking':cap===meshCapability?'3D file':cap===documentImportCapability?'document import':cap===chessCapability?'chess game':cap===communityQueryCapability?'community search':cap===contactBoundaryCapability?'contact controls':recommendationTitles[cap as RecommendationCapability]||'private result';}
function additionalCapabilityScreen(w:ProductWorld,cap:string,id='',task='',scope='own'){
 if(cap===restaurantCapability)return restaurantBookingScreen(id,task,'',scope);
 if(cap===meshCapability)return personalMeshScreen(id,task,scope);
 if(cap===documentImportCapability)return documentImportScreen(id,task,scope);
 if(cap===chessCapability)return personalChessScreen(id,task,scope);
 if(cap===communityQueryCapability)return communityQueryScreen(id,task,scope);
 if(cap===contactBoundaryCapability)return contactBoundaryScreen(id,task,'',scope);
 if(recommendationCapabilities.includes(cap as RecommendationCapability))return recommendationsScreen(cap as RecommendationCapability,id,task,scope);
}
