 return <PrivateVoiceWorkspace key={`${world.owner}:${resultId}:${taskId}:${draftScope}`} world={world} getWorld={()=>getState().world} run={run} capabilityId={capabilityId} resultId={resultId} taskId={taskId} request={request} draftScope={draftScope} initialDocument={initialDocument} onCreateDocument={()=>flow.push(libraryWorkspaceScreen('libraryTravelFamilyDocuments'))} onSaved={id=>{if(id!==resultId){run('private.voice.draft.clear',{scope:draftScope},{featureId:'AL-293',capabilityId,personId:world.owner,...(taskId?{sourceTaskId:taskId}:{})});flow.replace(privateVoiceScreen(capabilityId,id,taskId,request));}}} onConversationDraft={(draft,sourceRef,target)=>{const current=getState().world;if(current.owner!==world.owner||!current.identity.signedIn||!privateSourceCurrent(current,sourceRef)||!voiceSourceMatchesDraft(current,sourceRef,draft))return;let expected:ReturnType<typeof voiceConversationBridge>;try{expected=voiceConversationBridge(current,sourceRef.voiceId,draft.date,sourceRef.segmentIds);}catch{return;}if(expected.noteId!==target.noteId||expected.expectedVersion!==target.expectedVersion||JSON.stringify(expected.sourceRef)!==JSON.stringify(sourceRef))return;const scope=uid(),key=`${world.owner}:voice-conversation:${scope}`;let accepted=false;const value={owner:world.owner,noteId:target.noteId,expectedVersion:target.expectedVersion,sourceRef:JSON.stringify(sourceRef),value:JSON.stringify(draft)};update(w=>{if(w.owner!==world.owner||!w.identity.signedIn||!privateSourceCurrent(w,sourceRef)||!voiceSourceMatchesDraft(w,sourceRef,draft))return w;const n=target.noteId?rawPersonalNote(w,target.noteId):undefined;if(target.noteId&&(!n||String(n.version)!==target.expectedVersion))return w;accepted=true;return {...w,drafts:{...w.drafts,[key]:value}};});if(accepted)flow.push(conversationNotesScreen(target.noteId,scope));}} onSent={(id,originalTaskId)=>openTask(originalTaskId,id)} onOriginalTask={id=>openTask(id)} onDocumentSource={(source,pageId)=>flow.push(privateVoiceDocumentScreen(source,pageId))} onBack={()=>flow.pop()}/>;
