const emergencyAccessScreen=(planId='',taskId='',request='',intent='own')=>screen(`emergency-access-${planId||taskId||intent}`,'Emergency access',()=> <EmergencyAccessEntry planId={planId} taskId={taskId} request={request} intent={intent}/>);
function EmergencyAccessEntry({planId,taskId,request,intent}:{planId:string;taskId:string;request:string;intent:string}){
 const {world,run,update}=useProduct(),{getState}=useStore(),flow=useFlow(),scope=planId||taskId||intent,entryKey=`${world.owner}:emergency-access:${scope}`;
 let view:EmergencyView={...emptyEmergencyView(world.owner),selected:planId};
 const decode=(raw:string|undefined):EmergencyView|undefined=>{try{const value=JSON.parse(raw||'null');return value?.owner===world.owner&&typeof value.selected==='string'&&typeof value.editing==='boolean'&&value.draft&&typeof value.draft.name==='string'&&typeof value.sourceId==='string'&&typeof value.managerAttemptId==='string'&&typeof value.managerAccessDecision==='boolean'?value:undefined;}catch{return;}};
 const stored=decode(world.drafts[entryKey]?.view);if(stored)view={...view,...stored};
 const remembered=view.selected?emergencyPlan(world,view.selected):undefined;if(remembered){const canonical=decode(world.drafts[`${world.owner}:emergency-access:${remembered.id}`]?.view);if(canonical?.selected===remembered.id)view={...view,...canonical};}
 const selected=view.selected?emergencyPlan(world,view.selected):undefined,sourceTaskId=selected?.sourceTaskId||(!planId?taskId:'');
 if(selected&&view.sourceId&&!emergencySources(world,selected.id).some(s=>s.id===view.sourceId))view={...view,sourceId:'',managerAttemptId:'',managerAccessDecision:false};
 if(selected&&view.managerAttemptId&&!selected.attempts.some(a=>a.id===view.managerAttemptId))view={...view,managerAttemptId:''};
 const saveView=(next:EmergencyView)=>{if(next.owner!==world.owner)return;update(w=>{if(w.owner!==next.owner||!w.identity.signedIn)return w;const own=next.selected?emergencyPlan(w,next.selected):undefined;if(next.selected&&!own)return w;if(own&&next.sourceId&&!emergencySources(w,own.id).some(s=>s.id===next.sourceId))return w;if(own&&next.managerAttemptId&&!own.attempts.some(a=>a.id===next.managerAttemptId))return w;const value=JSON.stringify(next),drafts={...w.drafts},put=(key:string)=>{drafts[key]={...(drafts[key]||{}),view:value};};if(!planId||next.selected===planId)put(entryKey);if(own||scope==='own')put(`${w.owner}:emergency-access:own`);if(own)put(`${w.owner}:emergency-access:${own.id}`);return {...w,drafts};});
  if(planId&&!next.selected){flow.replace(libraryWorkspaceScreen('libraryEmergencyAccess'));return;}
  if(next.selected&&next.selected!==(planId||selected?.id)&&!view.editing){const current=getState().world,own=emergencyPlan(current,next.selected);if(current.owner===world.owner&&own)flow.replace(emergencyAccessScreen(own.id,own.sourceTaskId,request));}
 };
 const openTask=(id:string)=>{const current=getState().world,own=emergencyPlan(current,view.selected),xs=current.objects.filter(o=>o.id===id),t=xs[0];if(current.owner===world.owner&&current.identity.signedIn&&own&&own.sourceTaskId===id&&xs.length===1&&t.owner===current.owner&&t.kind==='agent-task'&&t.capabilityId===emergencyCapability&&t.resultId===own.id)flow.push(featureScreen('AL-293',{objectId:id,sourceId:id}));};
 if(!world.identity.signedIn)return <MobileScroll><section className="detail-content"><Info error>Sign in to your private emergency plans.</Info></section></MobileScroll>;
 if(planId&&!emergencyPlan(world,planId))return <MobileScroll><section className="detail-content"><Info error>This exact private emergency plan is unavailable. No other plan or account was selected.</Info><button className="secondary" onClick={()=>flow.pop()}>Back</button></section></MobileScroll>;
 const boundTaskId=selected?.sourceTaskId||taskId;
 if(boundTaskId){const xs=world.objects.filter(o=>o.id===boundTaskId),t=xs[0];if(xs.length!==1||t.owner!==world.owner||t.kind!=='agent-task'||t.capabilityId!==emergencyCapability||selected&&(t.resultId!==selected.id||selected.sourceTaskId!==boundTaskId))return <MobileScroll><section className="detail-content"><Info error>This exact task and emergency-plan pairing needs review.</Info><button className="secondary" onClick={()=>flow.pop()}>Back</button></section></MobileScroll>;if(!prototypeTaskSourceCurrent(world,t))return <PrivateTaskSourceHold taskId={boundTaskId}/>;}
 return <EmergencyAccessWorkspace key={`${world.owner}:${planId}:${taskId}:${intent}`} world={world} getWorld={()=>getState().world} run={run} planId={planId} taskId={sourceTaskId} initialRequest={request} viewState={view} onViewStateChange={saveView} onBack={()=>flow.pop()} onTask={openTask} onSaved={id=>{if(id===(planId||selected?.id))return;const current=getState().world,own=emergencyPlan(current,id);if(current.owner===world.owner&&current.identity.signedIn&&own)flow.replace(emergencyAccessScreen(own.id,own.sourceTaskId,request));}}/>;
}
const careLogScreen=(capabilityId:CareCap,profileId='',taskId='',request='')=>screen(`care-log-${capabilityId}-${profileId||taskId||'own'}`,capabilityId==='B2C-CAP-114'?'Care log':'Pet care',()=> <CareLogEntry capabilityId={capabilityId} profileId={profileId} taskId={taskId} request={request}/>);
function CareLogEntry({capabilityId,profileId,taskId,request}:{capabilityId:CareCap;profileId:string;taskId:string;request:string}){
 const {world,run,update}=useProduct(),{getState}=useStore(),flow=useFlow();const entryScope=profileId||taskId||'own',entryKey=`${world.owner}:care-log:${capabilityId}:${entryScope}`;
 let view:CareView={...emptyCareView(world.owner,capabilityId),selected:profileId};
 const ownView=(raw:string|undefined):CareView|undefined=>{try{const saved=JSON.parse(raw||'null');return saved?.owner===world.owner&&typeof saved.selected==='string'&&typeof saved.editingProfile==='boolean'&&typeof saved.editingEvent==='boolean'&&saved.profile&&saved.event&&typeof saved.eventId==='string'&&typeof saved.date==='string'&&typeof saved.grantId==='string'?saved:undefined;}catch{return;}};
 const saved=ownView(world.drafts[entryKey]?.view);if(saved)view={...view,...saved};
 if(view.selected&&careProfile(world,view.selected)?.capabilityId===capabilityId){const canonical=ownView(world.drafts[`${world.owner}:care-log:${capabilityId}:${view.selected}`]?.view);if(canonical?.selected===view.selected)view={...view,...canonical};}
 const selected=view.selected?careProfile(world,view.selected):undefined,selectedTaskId=selected?.capabilityId===capabilityId?selected.sourceTaskId:!profileId?taskId:'';
 const saveView=(next:CareView)=>{if(next.owner!==world.owner)return;update(w=>{if(!w.identity.signedIn||w.owner!==next.owner)return w;const own=next.selected?careProfile(w,next.selected):undefined;if(next.selected&&own?.capabilityId!==capabilityId)return w;const value=JSON.stringify(next),drafts={...w.drafts},put=(key:string)=>{drafts[key]={...(drafts[key]||{}),view:value};};put(`${w.owner}:care-log:${capabilityId}:own`);if(!profileId||next.selected===profileId)put(entryKey);if(own)put(`${w.owner}:care-log:${capabilityId}:${own.id}`);return {...w,drafts};});
  // Selecting an existing profile canonicalises once. New creation is canonicalised only by onSaved.
  if(profileId&&!next.selected){flow.replace(careLogScreen(capabilityId));return;}
  if(next.selected&&next.selected!==profileId&&!view.editingProfile){const own=careProfile(getState().world,next.selected);if(own?.capabilityId===capabilityId)flow.replace(careLogScreen(capabilityId,own.id,own.sourceTaskId,request));}
 };
 const openTask=(id:string)=>{const current=getState().world,own=careProfile(current,view.selected),matches=current.objects.filter(o=>o.id===id),task=matches[0];if(current.owner===world.owner&&current.identity.signedIn&&own?.capabilityId===capabilityId&&own.sourceTaskId===id&&matches.length===1&&task.owner===current.owner&&task.kind==='agent-task'&&task.capabilityId===capabilityId&&task.resultId===own.id)flow.push(featureScreen('AL-293',{objectId:id,sourceId:id}));};
 if(!world.identity.signedIn)return <MobileScroll><section className="detail-content"><Info error>Sign in to your private care records.</Info></section></MobileScroll>;
 if(profileId&&careProfile(world,profileId)?.capabilityId!==capabilityId)return <MobileScroll><section className="detail-content"><Info error>This exact private care profile is unavailable. No other person or pet was selected.</Info><button className="secondary" onClick={()=>flow.pop()}>Back</button></section></MobileScroll>;
 return <CareLogWorkspace key={`${world.owner}:${capabilityId}:${profileId}:${taskId}`} world={world} getWorld={()=>getState().world} run={run} capabilityId={capabilityId} profileId={profileId} taskId={selectedTaskId} initialRequest={request} viewState={view} onViewStateChange={saveView} onBack={()=>flow.pop()} onTask={openTask} onSaved={id=>{if(id===profileId)return;const current=getState().world,own=careProfile(current,id);if(current.owner===world.owner&&own?.capabilityId===capabilityId)flow.replace(careLogScreen(capabilityId,own.id,own.sourceTaskId,request));}}/>;
}
