function PersonalRecordsEntry({capabilityId,objectId,taskId,request}:{capabilityId:PersonalRecordCap;objectId:string;taskId:string;request:string}){
 const {world,run,update}=useProduct(),{getState}=useStore(),flow=useFlow();const entryScope=objectId||taskId||'own',entryKey=`${world.owner}:personal-records:${capabilityId}:${entryScope}`;let view={...emptyPersonalInventoryView(world.owner),selected:objectId};
 const ownView=(value:string|undefined)=>{try{const saved=JSON.parse(value||'null');return saved?.owner===world.owner&&typeof saved.selected==='string'&&saved.inventory&&saved.product&&saved.batch&&Array.isArray(saved.photoDrafts)&&Array.isArray(saved.selectedPhotos)?saved:undefined;}catch{return;}};
 const entry=ownView(world.drafts[entryKey]?.view);if(entry)view={...view,...entry};
 // Only an explicit selected own original can nominate its canonical saved view.
 // An intentional empty selection remains a list; no old canonical selected-ID can revive it.
 if(view.selected&&personalRecordOriginal(world,view.selected)?.capabilityId===capabilityId){const canonical=ownView(world.drafts[`${world.owner}:personal-records:${capabilityId}:${view.selected}`]?.view);if(canonical&&canonical.selected===view.selected)view={...view,...canonical};}
 const selectedOriginal=view.selected?personalRecordOriginal(world,view.selected):undefined,selectedTaskId=selectedOriginal?.capabilityId===capabilityId?selectedOriginal.sourceTaskId:!objectId?taskId:'';
 const props={world,getWorld:()=>getState().world,run,objectId,taskId:selectedTaskId,initialRequest:request,viewState:view,onViewStateChange:(next:typeof view)=>{if(next.owner!==world.owner)return;update(w=>{if(!w.identity.signedIn||next.owner!==w.owner)return w;const selected=next.selected?personalRecordOriginal(w,next.selected):undefined;if(next.selected&&selected?.capabilityId!==capabilityId)return w;const state=JSON.stringify(next),drafts={...w.drafts,[`${w.owner}:personal-records:${capabilityId}:own`]:{...(w.drafts[`${w.owner}:personal-records:${capabilityId}:own`]||{}),view:state}};if(!objectId||!next.selected||next.selected===objectId)drafts[entryKey]={...(w.drafts[entryKey]||{}),view:state};if(selected){const key=`${w.owner}:personal-records:${capabilityId}:${selected.id}`;drafts[key]={...(w.drafts[key]||{}),view:state};}return {...w,drafts};});if(objectId&&next.selected&&next.selected!==objectId){const selected=personalRecordOriginal(getState().world,next.selected);if(selected?.capabilityId===capabilityId)flow.replace(personalRecordsScreen(capabilityId,selected.id,selected.sourceTaskId,request));}},onBack:()=>flow.pop(),onSaved:(id:string)=>{if(id!==objectId&&!(objectId&&view.selected==='')){const r=personalRecordOriginal(getState().world,id);if(r&&r.capabilityId===capabilityId)flow.replace(personalRecordsScreen(capabilityId,r.id,r.sourceTaskId,request));}},onTask:(id:string)=>flow.push(featureScreen('AL-293',{objectId:id})),onRecipes:(rows:ReturnType<typeof pantryRecipeSnapshot>)=>{try{const source=capturePantryPlanningSource(getState().world,rows.map(p=>p.productId));flow.push(pantryRecipeReviewScreen(source,uid()));}catch{flow.push(screen('pantry-recipe-source-unavailable','Pantry review',()=> <MobileScroll><section className="detail-content"><Info error>The selected stock changed or is unavailable. Return to your pantry and review the original again.</Info><button className="secondary" onClick={()=>flow.pop()}>Back to my pantry</button></section></MobileScroll>));}},onAddMedia:()=>flow.push(screen('personal-photo-private-media','Your private media',()=> <MobileScroll><div className="detail-content"><MediaWorkspace/></div></MobileScroll>))};
 if(!world.identity.signedIn)return <MobileScroll><section className="detail-content"><Info error>Sign in to your private records.</Info></section></MobileScroll>;
 if(objectId&&personalRecordOriginal(world,objectId)?.capabilityId!==capabilityId)return <MobileScroll><section className="detail-content"><Info error>This exact private original is unavailable. No replacement record has been selected.</Info><button className="secondary" onClick={()=>flow.pop()}>Back</button></section></MobileScroll>;
 return capabilityId==='B2C-CAP-108'?<PersonalInventoryWorkspace key={`${world.owner}:${capabilityId}:${objectId}:${taskId}`} {...props}/>:capabilityId==='B2C-CAP-109'?<PersonalPantryWorkspace key={`${world.owner}:${capabilityId}:${objectId}:${taskId}`} {...props}/>:<PersonalPhotoArchiveWorkspace key={`${world.owner}:${capabilityId}:${objectId}:${taskId}`} {...props}/>;
}
const leisureDiscoveryScreen=(capabilityId:LeisureCap,resultId='',taskId='',request='')=>screen(`leisure-discovery-${resultId||taskId||capabilityId}`,'Your leisure choices',()=> <LeisureDiscoveryEntry capabilityId={capabilityId} resultId={resultId} taskId={taskId} request={request}/>);
function LeisureDiscoveryEntry({capabilityId,resultId,taskId,request}:{capabilityId:LeisureCap;resultId:string;taskId:string;request:string}){
 const {world,run}=useProduct(),{getState}=useStore(),flow=useFlow();
 const {draft,set}=useFeatureDraft(`leisure-discovery:${capabilityId}:${resultId||taskId||'new'}`,{view:''});let initial:LeisureDraft|undefined;
 try{const value=JSON.parse(draft.view);if(value?.owner===world.owner&&value.draft&&Array.isArray(value.draft.options)&&Array.isArray(value.draft.selectedIds)&&Array.isArray(value.draft.plan))initial=value.draft;}catch{}
 const openEvent=(id:string)=>{const current=getState().world,events=current.objects.filter(o=>o.id===id&&o.kind==='event');if(!current.identity.signedIn||events.length!==1||['cancelled','deleted','withdrawn'].includes(String(events[0].status)))return;const event=events[0];if(event.venueId&&current.venues.filter(v=>v.id===event.venueId&&v.operatorActive).length!==1)return;if(event.owner===current.owner){flow.push(featureScreen('AL-305',{objectId:id,...(event.venueId?{venueId:String(event.venueId)}:{})}));return;}const posts=current.posts.filter(p=>p.publishing?.eventId===id);if(posts.length===1&&!posts[0].archived&&['accepted','partial'].includes(posts[0].status)&&mayRead(current,posts[0])&&canReadPaidOriginal(current,posts[0])&&!current.people.some(p=>p.id===posts[0].author&&(p.blocked||p.blockedByOther)))flow.push(originalScreen(posts[0].id));};
 return <LeisureDiscoveryWorkspace key={`${world.owner}:${resultId}:${taskId}:${capabilityId}`} world={world} run={run} capabilityId={capabilityId} resultId={resultId} taskId={taskId} initialRequest={request} initialDraft={initial} onDraftChange={value=>set('view',JSON.stringify({owner:world.owner,draft:value}))} onSaved={id=>{if(id!==resultId){const r=ownLeisure(getState().world).find(v=>v.id===id);if(r)flow.replace(leisureDiscoveryScreen(r.capabilityId,r.id,r.sourceTaskId,r.draft.question));}}} onTask={id=>flow.push(featureScreen('AL-293',{objectId:id}))} onSpot={id=>{const current=getState().world;if(current.identity.signedIn&&current.venues.filter(v=>v.id===id&&v.operatorActive).length===1)flow.push(placeScreen(id));}} onEvent={openEvent} onWeek={id=>{const current=getState().world;if(current.identity.signedIn&&current.objects.filter(o=>o.id===id&&o.owner===current.owner&&o.kind==='week-plan').length===1)flow.push(weekPlannerScreen(id));}} onCreateWeek={()=>flow.push(weekPlannerScreen())} onBack={()=>flow.pop()}/>;
}
