function ParcelTrackingEntry({parcelId,taskId}:{parcelId:string;taskId:string}){const {world,run}=useProduct(),flow=useFlow();const {draft,set}=useFeatureDraft(`parcel-tracking:${parcelId||taskId||'own'}`,{view:''});let view=emptyParcelTrackingView(world.owner);try{const saved=JSON.parse(draft.view);if(saved?.owner===world.owner&&saved.draft&&saved.mode)view=saved;}catch{}return <ParcelTrackingWorkspace key={`${world.owner}:${parcelId}:${taskId}`} world={world} run={run} parcelId={parcelId} taskId={taskId} viewState={view} onViewStateChange={next=>set('view',JSON.stringify(next))} onBack={()=>flow.pop()} onChuck={id=>{const r=parcelRecords(world).find(v=>v.id===id);if(r)flow.push(featureScreen('AL-293',{objectId:r.sourceTaskId}));}} onConnections={()=>flow.push(appConnectionScreen('parcel'))} onOriginal={(o,p)=>flow.push(merchantCheckoutScreen(o,p))}/>;}
