function authorScreen(post: NostrPost, owner: string, current: ProductWorld) {
  const award=awardPostCampaign(current,post);
  if(award&&storyCampaignsFor(current).some(c=>c.id===award.id))return awardScreen({page:'story-profile',id:award.id,sourcePostId:post.id});
  const target = contentAuthorTarget(post, owner);
  return target.kind === "self"
    ? featureScreen("AL-028")
    : target.kind === "space"
      ? venuePublisherScreen(target.id)
      : featureScreen("AL-055", { personId: target.id });
}
const originalScreen = (id: string) => document.querySelector(".desktop-chrome") ? {id:`original-${id}`,render:()=> <OriginalContent id={id}/>} : screen(`original-${id}`, "Original content", () => <OriginalContent id={id}/>);
const editorScreen = (sourceId?: string) =>
  screen("compose", "Create a post", () => (
    <EditorPanel featureId="AL-113" context={{ sourceId }} />
  ));
function FeatureSurface({
  id,
  context,
  desktopRules=false,
  desktopVisit=false,
}: {
  id: string;
  context: Partial<ActionContext>;
  desktopRules?:boolean;
  desktopVisit?:boolean;
}) {
  const f = featureById(id);
  const { world } = useProduct();
  const flow = useFlow();
  const { setState } = useStore();
  const appRequest = world.objects.find(o => o.owner === world.owner && o.kind === "app-action" && (o.id === context.objectId || o.id === context.appActionId));
  if (appRequest) return <AppActionResult objectId={appRequest.id} />;
  const offerBooking =
    id === "AL-273" &&
    world.objects.find(
      (o) =>
        o.id === context.objectId &&
        o.owner === world.owner &&
        o.kind === "booking" &&
        o.offerId,
    );
  if (offerBooking) return <VenueOfferRequest bookingId={offerBooking.id} />;
  if (id === "AL-273" && context.offerId && context.postId)
    return <VenueOfferDetail postId={context.postId} />;
  if (!f) return <Info error>Unknown action.</Info>;
  if(id==='AL-306')return <EventSeriesBridge context={context}/>;
  if(id==='AL-076')return <CircleExperience context={context}/>;
  if(id==='AL-317')return <VisitJourneyBridge journeyId={context.objectId} venueId={context.venueId}/>;
  if (id === "AL-136") return <ProfileSocialLinksEditor/>;
  if(id==="AL-098") return <div className="feature-surface" data-feature-id={id}><VenueHoursEntry venueId={context.venueId||world.activeVenueId}/></div>;
  if (["AL-095","AL-097"].includes(id)) return <div className="feature-surface" data-feature-id={id}><VenuePerksEntry venueId={context.venueId||world.activeVenueId} category={id==="AL-097"?"welcome":"all"}/></div>;
  if (["AL-034","AL-037","AL-053"].includes(id)) return <div className="feature-surface" data-feature-id={id}><SpotCommunityEntry venueId={context.venueId||world.activeVenueId} write={id==="AL-053"}/></div>;
  if (
    f.view === "agent" &&
    context.objectId &&
    world.objects.some(
      (o) =>
        o.id === context.objectId &&
        o.owner === world.owner &&
        o.kind === "agent-task",
    )
  )
    return <ChuckTaskExperience id={context.objectId} />;
  const ctx = {
    ...context,
    featureId: id,
    venueId: context.venueId || world.activeVenueId,
  };
  let body: ReactNode;
  switch (f.view) {
    case "welcome":
      body = <WelcomePanel />;
      break;
    case "auth":
      body = <AuthPanel />;
      break;
    case "profile-field":
    case "profile-preview":
    case "profile-photo":
    case "profile-suggestion":
      body = <ProfileEditor feature={f} />;
      break;
    case "venues":
    case "venue-info":
    case "venue-state":
      body =
        f.view === "venue-info" && id === "AL-035" && !context.detail ? (
          <PlaceExperience venueId={ctx.venueId} />
        ) : (
          <VenuePanel feature={f} context={ctx} sourceContext={context} desktopRules={desktopRules&&closedHouseRulesContext(id,context)} desktopVisit={desktopVisit&&closedSpotVisitContext(id,context)} />
        );
      break;
    case "following":
      body = <PublicConnectionsPanel feature={f} context={ctx} />;
      break;
    case "people":
    case "suggestions":
    case "connection-control":
    case "introduction":
      body =
        id === "AL-055" && context.personId ? (
          <PublicProfile personId={context.personId} />
        ) : (
          <ConnectionsPanel feature={f} context={ctx} />
        );
      break;
    case "private-chat":
      body =
        context.personId === "alex" &&
        (!context.chatId || ["alex", "person:alex"].includes(context.chatId)) &&
        !context.objectId ? (
          <Chat id="alex" />
        ) : (
          <ControlPanel kind="private-person-chat" feature={f} context={ctx} />
        );
      break;
    case "assessment":
      body = <AssessmentPanel feature={f} />;
      break;
    case "messenger":
      body =
        id === "AL-090" ? (
          <PublicProfile personId={context.personId || "alex"} />
        ) : id === "AL-089" ? (
          <SharedPersonality personId={context.personId || "alex"} />
        ) : ["AL-083", "AL-084", "AL-085", "AL-226", "AL-252"].includes(id) ? (
          (context.personId &&
          !["alex", "chuck", "circle"].includes(context.personId)) ||
          (context.personId === "alex" &&
            ((context.chatId && !["alex", "person:alex"].includes(context.chatId)) || context.objectId)) ? (
            <ControlPanel
              kind="private-person-chat"
              feature={f}
              context={ctx}
            />
          ) : (
            <Chat id={(context.personId || "alex") as ChatId} />
          )
        ) : (
          <MessengerPanel feature={f} context={ctx} />
        );
      break;
    case "community-life":
    case "events":
      body =
        id === "AL-307" ? (
          <CircleExperience context={context} />
        ) : id === "AL-305" && context.objectId ? (
          <EventExperience context={context} />
        ) : (
          <CommunityPanel feature={f} context={ctx} />
        );
      break;
    case "nostr-browser":
      body = <NostrBrowser featureId={id} context={ctx} />;
      break;
    case "editor":
      body = <EditorPanel featureId={id} context={ctx} />;
      break;
    case "publication":
      body = <PublicationPanel context={ctx} />;
      break;
    case "post-actions":
    case "post-interaction":
      body = <OriginalContent id={context.postId || "note-1"} />;
      break;
    case "wallets":
    case "wallet-detail":
    case "payment":
      body =
        f.view === "wallets" ? (
          <WalletsOverview />
        ) : f.view === "wallet-detail" && id !== "W15" ? (
          <WalletAccount
            walletId={
              context.walletId ||
              (id === "W04" ? "utexo" : id === "W11" ? "rgb" : "ln")
            }
          />
        ) : (
          <WalletPanel feature={f} context={ctx} />
        );
      break;
    case "vertical":
      body = <VerticalPanel context={ctx} />;
      break;
    case "ordering":
      body = <OrderingPanel featureId={id} context={ctx} />;
      break;
    case "content-rights":
    case "rgb-recovery":
      body = <RightsPanel feature={f} context={ctx} />;
      break;
    case "creator-offer":
    case "subscribers":
    case "revenue":
    case "media-provider":
    case "linkhub":
    case "badges":
      body = id === "AL-201" ? <InstagramImportBridge/> :
        id === "AL-177" || (f.view === "linkhub" && id !== "AL-201") ? (
          <CreatorProfileWorkbench />
        ) : (
          <CreatorPanel feature={f} context={ctx} />
        );
      break;
    case "business":
    case "relationship":
    case "followup":
    case "calendar-permission":
    case "booking":
    case "handoff":
      body = ["AL-273", "AL-274", "AL-297"].includes(id) ? (
        <SpaceBooking feature={f} context={ctx} />
      ) : (
        <ProfessionalPanel feature={f} context={ctx} />
      );
      break;
    case "agent":
    case "identity":
    case "operator":
    case "notifications":
    case "support":
    case "contact-qr":
    case "future":
    case "connectivity":
    case "review-matrix":
    case "review":
      body = <ControlPanel feature={f} context={ctx} />;
      break;
    default:
      body = <Info error>This action has no bound view.</Info>;
  }
  return (
    <div
      className="feature-surface"
      data-feature-id={id}
      data-function-ids={id}
      data-source-view={f.view}
    >
      {body}
      <BottomSheet open={false} onOpenChange={() => {}} title="" />
    </div>
  );
}
function NextActions({
  featureId,
  context = {},
  showMore = true,
}: {
  featureId: string;
  context?: Partial<ActionContext>;
  showMore?: boolean;
}) {
  const flow = useFlow();
  const { world, update } = useProduct();
  const [notice, setNotice] = useState("");
  const f = featureById(featureId);
  const suggestions = nextStepSuggestions(world, context);
  const more = (f?.related || []).slice(0, 4).filter(id => id !== featureId);
  const open = (shown: NextStep) => {
    const s = nextStepSuggestions(world, context).find(current => current.id === shown.id);
    if (!s) { setNotice("This suggestion changed. Check the original before continuing."); return; }
    if (s.action === "meal-shopping") {
      update(w => ({ ...w, drafts: { ...w.drafts, [`${w.owner}:personal-plan-view:${s.originalId}`]: { ...(w.drafts[`${w.owner}:personal-plan-view:${s.originalId}`] || {}), tab: "Shopping list" } } }));
      if (flow.current.id !== `personal-plan-${s.originalId}`) flow.push(personalPlanScreen(s.originalId));
    } else if (s.action === "meal-ingredients") flow.push(personalPlanEditorScreen("meals", s.originalId));
    else if (s.action === "booking-arrival" && s.venueId) {
      update(w => ({ ...w, drafts: { ...w.drafts, [`${w.owner}:place-view:${s.venueId}`]: { ...(w.drafts[`${w.owner}:place-view:${s.venueId}`] || {}), tab: "Visit" } } }));
      flow.push(placeScreen(s.venueId));
    } else if (s.action === "booking-reminder") flow.push(reminderScreen("", s.originalId));
    else if (s.action === "app-review" && s.providerId && s.actionId) {
      const route = appActionScreen(s.providerId, s.actionId, s.originalId);
      if (flow.current.id === `app-request-${s.originalId}`) flow.replace(route); else flow.push(route);
    } else if (s.action === "app-permissions" && s.providerId) flow.push(appConnectionScreen(s.providerId));
    else if (s.action === "quota-review") flow.push(craysContractScreen(s.originalId));
  };
  if (!suggestions.length && !context.sourceTaskId && (!showMore || !more.length)) return null;
  return <section className="next-actions contextual-next-actions">
    {suggestions.map(s => <article className="next-step-card" key={s.id}>
      <div className="next-step-heading"><span className="next-step-symbol">{s.image ? <img src={asset(s.image)} alt="" /> : s.icon === "shopping" || s.icon === "ingredients" ? <BowlFood size={23} /> : s.icon === "arrival" ? <MapPin size={23} /> : s.icon === "reminder" ? <Clock size={23} /> : s.icon === "usage" ? <Pulse size={23} /> : s.icon === "permission" ? <ShieldCheck size={23} /> : <NotePencil size={23} />}</span><strong>{s.title}</strong><IconButton label={`Hide suggestion: ${s.title}`} onClick={() => update(w => ({ ...w, settings: { ...w.settings, [nextStepDismissalKey(s)]: true } }))}><X size={17} /></IconButton></div>
      <p>{s.reason}</p><button className="next-step-open" onClick={() => open(s)}>{s.cta || (s.action === "meal-shopping" ? "Open shopping list" : s.action === "meal-ingredients" ? "Add my ingredients" : s.action === "booking-arrival" ? "See visit details" : s.action === "booking-reminder" ? "Choose a reminder" : s.action === "quota-review" ? "Check allowance & options" : "Review permissions")}<CaretRight size={17} /></button>
    </article>)}
    {!!notice && <Info error>{notice}</Info>}
    {context.sourceTaskId && <Row title="View originating Chuck task" onClick={() => flow.push(featureScreen("AL-293", { objectId: context.sourceTaskId }))} />}
    {showMore && more.length > 0 && <details className="next-step-more"><summary>More options <CaretDown size={17} /></summary>{more.map(id => <Row key={id} title={contextualActionLabel(id)} onClick={() => flow.push(featureScreen(id, context))} />)}</details>}
  </section>;
}
