    if(delta>0&&!p){setResult({ok:false,world,objectId:"",message:"This item is no longer available. Remove it or choose from the current menu."});return false;}
    let line:OrderBasketLine|undefined;
    try{line=delta>0&&p?.catalogue?catalogueLineSnapshot(world,venue.id,id,variant,1,selections):undefined;}catch(error){setResult({ok:false,world,objectId:"",message:String((error as Error).message)});return false;}
    const row = next.find((i) => i.id === id && (i.variantId?i.variantId===variant:i.variant===variant) && i.configurationKey===(configurationKey||line?.configurationKey));
