    if(id==="coffee"||item?.catalogue?.kind==="drink"||/coffee|espresso/.test(name)) return <Coffee size={32}/>;
    if(id==="bowl"||/bowl|salad|soup/.test(name)) return <BowlFood size={32}/>;
