 const restoreFocus=()=>{const el=restore.current;window.setTimeout(()=>{if(el?.isConnected&&el.getClientRects().length&&!el.closest('[data-flow-current="false"]'))el.focus({preventScroll:true});else document.querySelector<HTMLElement>('[data-flow-current="true"] .community-membership-heading h1')?.focus({preventScroll:true});},0);};
