 if(view==='plans')return <><WebCommunityMembershipPlans world={world} groupId={id} period={catalogue.period==='yearly'?'yearly':'monthly'} onPeriod={value=>setCatalogue('period',value)} onReview={reviewOffer} onBack={()=>flow.pop()} onMemberships={account} onReceipts={receipts}/>{feedback&&<p className="community-membership-feedback" role="status">{feedback}</p>}</>;
 if(view==='application')return <WebCommunityMembershipApplication world={world} id={id} backLabel={backLabel} draft={application} set={setApplication} feedback={feedback} onBack={()=>flow.pop()} onSubmit={()=>action('submit',{answer:application.answer,newsletter:application.newsletter==='Yes'?'Yes':'No',terms:application.terms,renewal:'No'})} onExampleReview={outcome=>action('example.review-result',{outcome,exampleSource:'fictional-external-community-review',note:outcome==='accepted'?'Application accepted by the fictional community reviewer.':'The fictional community reviewer asks for a different contribution. Review a new application if you wish.'})} onContinue={()=>flow.push(communityMembershipScreen('payment',id,'your application'))} onRestart={()=>{if(r)reviewOffer(r.offer,true);}}/>;
