 const chuck=(id:string,version:string,choices:EvidenceChuckChoices,snapshot:string)=>{let expected="";const current=getState();if(current.world.owner!==world.owner||!current.world.identity.signedIn)return "Open your own current discussion.";try{const p=evidenceChuckPreview(current.world,id,version,choices);if(p.key!==snapshot)return "The selected fields changed. Review again.";expected=p.text;}catch(e){return e instanceof Error?e.message:String(e);}setState(s=>{if(s.world.owner!==world.owner||!s.world.identity.signedIn)return s;try{const p=evidenceChuckPreview(s.world,id,version,choices);if(p.key!==snapshot)return s;return {...s,context:{...s.context,chuck:{featureId:"AL-248",objectId:id,sourceId:id}},drafts:{...s.drafts,chuck:p.text}};}catch{return s;}});if(getState().drafts.chuck!==expected||getState().context.chuck?.objectId!==id)return "The source changed. No draft opened.";flow.push(chatScreen("chuck"));return null;};
