const recipePlanningScreen=(capabilityId:RecipePlanCapability,taskId='',planningId='',request='',initialPlanningDraft?:RecipePlanningDraft,draftScope='')=>screen(`recipe-planning-${planningId||taskId||draftScope||capabilityId}`,'Your kitchen plan',()=> <RecipeEntry initialRecipeId="" capabilityId={capabilityId} taskId={taskId} planningId={planningId} request={request} initialPlanningDraft={initialPlanningDraft} draftScope={draftScope}/>);
function RecipeEntry({initialRecipeId,capabilityId='B2C-CAP-042',taskId='',planningId='',request='',initialPlanningDraft,draftScope=''}:{initialRecipeId:string;capabilityId?:RecipePlanCapability;taskId?:string;planningId?:string;request?:string;initialPlanningDraft?:RecipePlanningDraft;draftScope?:string}){const {world,run,update}=useProduct();const {setState,getState}=useStore();const flow=useFlow();const draftKey=`${world.owner}:recipe-planning:${planningId||taskId||draftScope||capabilityId}`;const retainedDraft=readRecipePlanningDraft(world,draftKey,capabilityId,planningId,taskId);return <RecipeWorkspace key={`${world.owner}:${initialRecipeId}:${taskId}:${planningId}:${draftScope}`} world={world} run={run} initialPlanningDraft={initialPlanningDraft} retainedPlanningDraft={retainedDraft} onPlanningDraftChange={draft=>{const owner=world.owner;update(w=>w.owner!==owner||!w.identity.signedIn?w:{...w,drafts:{...w.drafts,[draftKey]:{...(w.drafts[draftKey]||{}),value:JSON.stringify({owner,capabilityId,planningId,taskId:ownRecipePlanning(w).find(r=>r.id===planningId)?.sourceTaskId||taskId,baseVersion:ownRecipePlanning(w).find(r=>r.id===planningId)?.version||0,draft})}}});}} initialRecipeId={initialRecipeId} capabilityId={capabilityId} taskId={taskId} planningId={planningId} initialRequest={request} onCulinary={cap=>flow.push(recipePlanningScreen(cap,'','','My own culinary choices for '+(cap==='B2C-CAP-045'?'ingredient alternatives':'leftover ideas')))} onPlanningOpen={id=>{const latest=getState().world,r=ownRecipePlanning(latest).find(r=>r.id===id);if(latest.owner===world.owner&&r)flow.push(recipePlanningScreen(r.capabilityId,r.sourceTaskId,r.id,r.draft.request));}} onPlanningSaved={id=>{const r=ownRecipePlanning(getState().world).find(v=>v.id===id);if(r&&r.id!==planningId)flow.replace(recipePlanningScreen(r.capabilityId,r.sourceTaskId,r.id,r.draft.request));}} onTask={id=>flow.push(featureScreen('AL-293',{objectId:id}))} onBack={()=>flow.pop()} onIntake={context=>flow.push(recipeIntakeScreen(context))} onQuestion={(id,authority,question)=>{const latest=getState(),recipe=availableRecipe(latest.world,id);if(latest.world.owner!==world.owner||!recipe||recipeAuthority(recipe)!==authority)return;setState(s=>{const current=availableRecipe(s.world,id);return s.world.owner!==world.owner||!current||recipeAuthority(current)!==authority?s:{...s,context:{...s.context,chuck:{featureId:'AL-248',capabilityId:'B2C-CAP-043',sourceId:`recipe-example:${id}:v${current.version}`}},drafts:{...s.drafts,chuck:`My question about the fictional recipe example “${current.name}” (version ${current.version}):\n${question}\nOnly this recipe reference is selected. My collections, cooking history, diary, preferences and health data are not included. Explain or propose changes for separate review; do not order, log intake or publish anything.`}};});flow.push(chatScreen('chuck'));}}/>;}
