function VerticalPanel({ context }: { context: Partial<ActionContext> }) {
  const { world, run } = useProduct();
  const flow = useFlow();
  const { draft, set } = useFeatureDraft(
    `vertical:${context.venueId || world.activeVenueId}`,
    {
      venueId: context.venueId || world.activeVenueId,
      section: context.purpose || "Overview",
      portions: "1",
      day: "2026-10-24",
      sets: "",
      reps: "",
      weight: "",
      duration: "",
      feedback: "",
      goal: "General movement",
      plan: "Sample plan v1",
      variant: "Natural",
      quantity: "1",
      size: "500 ml",
      text: "",
      stock: "0",
      permission: "No",
    },
  );
  const [feedback, setFeedback] = useState<ActionResult | null>(null);
  const [editing, setEditing] = useState("");
  const venue =
    world.venues.find((v) => v.id === draft.venueId) || world.venues[0];
  const ctx = { ...context, featureId: "AL-248", venueId: venue.id };
  const records = world.objects.filter(
    (o) => o.owner === world.owner && o.venueId === venue.id,
  );
  const save = (
    kind: string,
    name: string,
    data: Record<string, string> = {},
  ) => {
    const r = run(
      editing ? "object.update" : "object.create",
      { kind, name, ...data },
      { ...ctx, objectId: editing || undefined },
    );
    setFeedback(r);
    if (r.ok) setEditing("");
  };
  const section = (name: string) => {
    if(venue.type === "Gym & wellbeing"){
      if(name === "Training" || name === "Training log"){flow.push(trainingWorkspaceScreen());return;}
      if(name === "Recipes" || name === "Shopping list"){flow.push(recipeWorkspaceScreen());return;}
      if(name === "Nutrition plan"){flow.push(nutritionWorkspaceScreen());return;}
      if(name === "Coaching"){flow.push(fitnessCoachingScreen());return;}
      if(name === "Membership"){flow.push(ownMembershipsScreen());return;}
    }
    set("section",name);
  };
  const portions = Math.max(1, Math.min(8, Number(draft.portions) || 1));
  if(venue.id===gymRetailVenueId&&['Store','Product details','Store order'].includes(draft.section))return <OrderingPanelBody featureId="AL-141" context={ctx}/>;
  const gym = [
    "Training",
    "Coaching",
    "Recipes",
    "Nutrition plan",
    "Shopping list",
    "Training log",
    "Membership",
    "Health permissions",
  ];
  return (
    <MobileScroll>
      <div className="detail-content vertical-service-experience">
        <img className="vertical-service-photo" src={asset(venue.image)} alt={`Illustrative atmosphere for ${venue.name}`}/>
        <span className="eyebrow">{venue.name}</span>
        <h1>
          {draft.section === "Overview"
            ? "Make the most of this place."
            : draft.section}
        </h1>
        <label className="product-field">
          <span>Place</span>
          <select
            aria-label="Service venue"
            value={venue.id}
            onChange={(e) => {
              set("venueId", e.target.value);
              set("section", "Overview");
              setEditing("");
            }}
          >
            {world.venues.map((v) => (
              <option key={v.id} value={v.id}>
                {v.name}
              </option>
            ))}
          </select>
        </label>
        <p className="context-note">
          Illustrative service records · independent of social visibility · no
          external provider is connected.
        </p>
        {draft.section === "Overview" ? (
          <>
            {venue.type === 'Gym & wellbeing'&&<Row title="Nutrition with Chuck" subtitle="Recipes, all 16 nutrients and your week or month" icon={<Scales size={24}/>} onClick={()=>flow.push(nutritionWorkspaceScreen())}/>}
            {venue.services.map((name) => (
              <Row
                key={name}
                title={name}
                icon={name === "Coffee" ? <Coffee size={24}/> : name.includes("booking") ? <Clock size={24}/> : name.includes("event") ? <Ticket size={24}/> : name === "Lost & found" ? <Archive size={24}/> : <Gear size={24}/>}
                onClick={() =>
                  (name === "Coffee" || name === "Shop" && venue.id===gymRetailVenueId)
                    ? flow.push(featureScreen("AL-141", ctx))
                    : name.includes("booking") || name === "Meeting room"
                      ? flow.push(
                          featureScreen("AL-297", { ...ctx, purpose: name }),
                        )
                      : section(name)
                }
              />
            ))}
            {venue.type === "Gym & wellbeing" &&
              gym
                .filter((name) => !venue.services.includes(name))
                .map((name) => (
                  <Row key={name} title={name} onClick={() => section(name)} />
                ))}
            <Row
              title={venue.id===gymRetailVenueId?"Gym shop":"Store & product comparison"}
              icon={<Scales size={24}/>}
              onClick={() => venue.id===gymRetailVenueId?flow.push(featureScreen("AL-141",ctx)):section("Store")}
            />
            <Row
              title="Your service records here"
              icon={<ListChecks size={24}/>}
              onClick={() => section("Your records")}
            />
          </>
        ) : draft.section === "Recipes" ? (
          <WebFieldGroup id="VerticalPanel-fields-34">
            <img
              className="venue-cover"
              src={asset("venue-table.png")}
              alt="CRAYS shared-table atmosphere; not a recipe photograph"
            />
            <p className="source-caption">
              Illustrative recipe · oat bowl v1 · original quantities retained
            </p>
            <h2>A simple oat bowl</h2>
            <p>
              One serving · 10 minutes · vegetarian. Nutrition values have not
              been supplied and are not estimated.
            </p>
            <Field
              label="Servings"
              value={draft.portions}
              options={["1", "2", "3", "4", "5", "6", "7", "8"]}
              onChange={(v) => set("portions", v)}
            />
            <DetailList
              items={[
                ["Oats", `${50 * portions} g`],
                ["Milk or chosen alternative", `${150 * portions} ml`],
                ["Banana", `${portions} whole`],
                ["Nutritional analysis", "Not supplied"],
              ]}
            />
            <h2>Preparation</h2>
            <ol>
              <li>Combine the oats and chosen milk in a bowl.</li>
              <li>Rest until the oats soften to your preference.</li>
              <li>Slice the banana and add before serving.</li>
            </ol>
            <p>
              Check ingredients and allergens with the original supplier. No
              personalised health claim is made.
            </p>
            <Field
              label="Meal day"
              value={draft.day}
              type="date"
              onChange={(v) => set("day", v)}
            />
            <button
              className="primary"
              onClick={() =>
                save("meal", "Oat bowl", {
                  day: draft.day,
                  portions: String(portions),
                  sourceVersion: "oat-bowl-v1",
                  status: "planned",
                })
              }
            >
              Add this version to nutrition plan
            </button>
            <button
              className="secondary"
              onClick={() => section("Shopping list")}
            >
              Review ingredients for shopping
            </button>
          </WebFieldGroup>
        ) : draft.section === "Nutrition plan" ? (
          <>
            <Field
              label="Meal day"
              value={draft.day}
              type="date"
              onChange={(v) => set("day", v)}
            />
            {records
              .filter((o) => o.kind === "meal" && o.day === draft.day)
              .map((o) => (
                <section className="result-record" key={o.id}>
                  <h2>{String(o.name)}</h2>
                  <p>
                    {String(o.portions)} servings · {String(o.sourceVersion)}
                  </p>
                  <button
                    className="secondary"
                    onClick={() => {
                      setEditing(o.id);
                      set("portions", String(o.portions));
                      section("Recipes");
                    }}
                  >
                    Correct this meal
                  </button>
                  <button
                    className="quiet"
                    onClick={() =>
                      setFeedback(
                        run("object.delete", {}, { ...ctx, objectId: o.id }),
                      )
                    }
                  >
                    Remove this meal
                  </button>
                </section>
              ))}
            <Row
              title="Choose an original recipe"
              onClick={() => section("Recipes")}
            />
          </>
        ) : draft.section === "Shopping list" ? (
          <>
            <h2>Oat bowl · {portions} servings</h2>
            <p>
              Source: oat-bowl-v1. Quantities remain in their original units.
            </p>
            <Field
              label="Oats already at home (g)"
              value={draft.stock}
              type="number"
              onChange={(v) => set("stock", v)}
            />
            <DetailList
              items={[
                [
                  "Oats needed",
                  `${Math.max(0, 50 * portions - Math.max(0, Number(draft.stock) || 0))} g`,
                ],
                ["Milk or alternative", `${150 * portions} ml`],
                ["Bananas", `${portions}`],
              ]}
            />
            <button
              className="primary"
              onClick={() =>
                save("shopping-list", "Ingredients for oat bowl", {
                  sourceVersion: "oat-bowl-v1",
                  portions: String(portions),
                  oatsRequired: String(
                    Math.max(
                      0,
                      50 * portions - Math.max(0, Number(draft.stock) || 0),
                    ),
                  ),
                  milkMl: String(150 * portions),
                  bananas: String(portions),
                  status: "reviewed-not-purchased",
                })
              }
            >
              Save reviewed shopping requirements
            </button>
            <Info>
              The store catalogue below does not claim to stock these
              ingredients. Substitutions require your review.
            </Info>
            <Row
              title="Open this venue’s sample store"
              onClick={() => section("Store")}
            />
          </>
        ) : ["Training", "Training log"].includes(draft.section) ? (
          <WebFieldGroup id="VerticalPanel-fields-35">
            <Row title="Training with Chuck" subtitle="Plans, exercise pictures, videos and private workouts" icon={<Barbell size={24}/>} onClick={()=>flow.push(trainingWorkspaceScreen())}/>
            <p className="source-caption">Earlier training entries remain available below.</p>
            <h2>{draft.plan}</h2>
            <p>
              General movement · source exercise: seated rest and reflection.
              This fixture provides no prescribed load, repetitions or medical
              advice.
            </p>
            <Field
              label="Plan version"
              value={draft.plan}
              options={["Sample plan v1", "Proposed plan v2"]}
              onChange={(v) => set("plan", v)}
            />
            <p>
              A changed version is saved only when you explicitly save an entry;
              existing entries retain their version.
            </p>
            <Field
              label="Session date"
              value={draft.day}
              type="date"
              onChange={(v) => set("day", v)}
            />
            {[
              ["sets", "Sets"],
              ["reps", "Repetitions"],
              ["weight", "Weight (kg)"],
              ["duration", "Duration (minutes)"],
            ].map(([key, label]) => (
              <Field
                key={key}
                label={label}
                value={draft[key]}
                type="number"
                onChange={(v) => set(key, v)}
              />
            ))}
            <Field
              label="Session feedback"
              value={draft.feedback}
              type="textarea"
              onChange={(v) => set("feedback", v)}
            />
            <button
              className="primary"
              onClick={() =>
                save("training-log", "Your training entry", {
                  date: draft.day,
                  sets: draft.sets,
                  reps: draft.reps,
                  weight: draft.weight,
                  duration: draft.duration,
                  text: draft.feedback,
                  planVersion: draft.plan,
                  status: "recorded-by-you",
                })
              }
            >
              {editing
                ? "Save correction to this entry"
                : "Save this private training entry"}
            </button>
            {records
              .filter((o) => o.kind === "training-log")
              .map((o) => (
                <section key={o.id} className="result-record">
                  <h3>{String(o.date)}</h3>
                  <p>
                    {String(o.sets)} sets · {String(o.reps)} repetitions ·{" "}
                    {String(o.weight)} kg · {String(o.duration)} min
                  </p>
                  <p>
                    {String(o.planVersion)} · {String(o.text)}
                  </p>
                  <button
                    className="secondary"
                    onClick={() => {
                      setEditing(o.id);
                      for (const key of ["sets", "reps", "weight", "duration"])
                        set(key, String(o[key] || ""));
                      set("feedback", String(o.text || ""));
                    }}
                  >
                    Correct this original entry
                  </button>
                </section>
              ))}
            <Row
              title="Ask your coach about this plan"
              onClick={() => section("Coaching")}
            />
          </WebFieldGroup>
        ) : draft.section === "Store" ? (
          <>
            <h2>Compare before choosing.</h2>
            <Carousel ariaLabel="Sample product comparison">
              {["500 ml", "750 ml"].map((size) => (
                <section className="result-record" key={size}>
                  <h3>Everyday bottle · {size}</h3>
                  <p>
                    Illustrative product · capacity {size}. Material and
                    measurements require the seller’s verified specification.
                  </p>
                  <p>
                    Natural or navy · price and availability to be confirmed.
                  </p>
                  <button
                    className="secondary"
                    onClick={() => {
                      set("size", size);
                      section("Product details");
                    }}
                  >
                    Review {size} bottle
                  </button>
                </section>
              ))}
            </Carousel>
            <Info>
              No verified product photographs or stock feed have been supplied.
              The prototype does not substitute unrelated venue imagery.
            </Info>
          </>
        ) : draft.section === "Product details" ? (
          <WebFieldGroup id="VerticalPanel-fields-36">
            <h2>Everyday bottle · {draft.size}</h2>
            <Field
              label="Product variant"
              value={draft.variant}
              options={["Natural", "Navy"]}
              onChange={(v) => set("variant", v)}
            />
            <Field
              label="Quantity"
              value={draft.quantity}
              options={["1", "2", "3", "4"]}
              onChange={(v) => set("quantity", v)}
            />
            <DetailList
              items={[
                ["Seller", venue.name],
                ["Price", "To be agreed"],
                ["Availability", "Awaiting seller"],
                ["Collection / delivery", "Review seller’s conditions"],
                ["Returns", "Original order and seller terms required"],
              ]}
            />
            <button
              className="primary"
              onClick={() =>
                save("store-order", "Everyday bottle", {
                  size: draft.size,
                  variant: draft.variant,
                  quantity: draft.quantity,
                  status: "quote-requested",
                  priceStatus: "Not set",
                  sourceVersion: "bottle-demo-v1",
                })
              }
            >
              Request this exact product quote
            </button>
            <Row
              title="Orders, delivery & return requests"
              onClick={() => section("Your records")}
            />
          </WebFieldGroup>
        ) : draft.section === "Membership" ? (
          <>
            <h2>Your service entitlement</h2>
            <DetailList
              items={[
                ["Source", venue.grant],
                ["Community membership", venue.membership],
                ["Paid services", "Not implied by social membership"],
                [
                  "Term, price & included sessions",
                  "Individual contract not supplied",
                ],
              ]}
            />
            <button
              className="secondary"
              onClick={() =>
                save("membership-change", "Service membership review", {
                  status: "change-requested",
                  terms: "Responsible venue must confirm",
                })
              }
            >
              Request a contract or plan change
            </button>
            <button
              className="secondary"
              onClick={() =>
                save(
                  "membership-cancellation",
                  "Membership cancellation review",
                  { status: "requested-no-automatic-refund" },
                )
              }
            >
              Request cancellation review
            </button>
          </>
        ) : draft.section === "Health permissions" ? (
          <>
            <Field
              label="Allow selected training data for this venue’s coaching"
              value={draft.permission}
              options={["No", "Yes"]}
              onChange={(v) => set("permission", v)}
            />
            <button
              className="primary"
              onClick={() =>
                setFeedback(
                  run(
                    "settings.save",
                    {
                      key: `training-permission:${venue.id}`,
                      value: draft.permission,
                    },
                    ctx,
                  ),
                )
              }
            >
              Save this separate purpose permission
            </button>
            <Info>
              No wearable or health provider is connected. This does not grant
              matching, public sharing or access to other accounts.
            </Info>
            <p>
              Current permission:{" "}
              {world.settings[`training-permission:${venue.id}`] === true
                ? "Allowed for the stated purpose"
                : "Not allowed"}
            </p>
          </>
        ) : draft.section === "Your records" ? (
          <>
            {records
              .filter((o) =>
                [
                  "service",
                  "store-order",
                  "return-request",
                  "shopping-list",
                  "membership-change",
                  "membership-cancellation",
                ].includes(String(o.kind)),
              )
              .map((o) => (
                <section className="result-record" key={o.id}>
                  <h2>{String(o.name)}</h2>
                  <p>
                    {String(o.status)} · {o.id}
                  </p>
                  <p>
                    {String(o.variant || "")} {String(o.size || "")}
                  </p>
                  {o.kind === "store-order" && (
                    <button
                      className="secondary"
                      onClick={() =>
                        save("return-request", `Return review: ${o.name}`, {
                          originalOrder: o.id,
                          status: "eligibility-review",
                          reason: draft.text,
                        })
                      }
                    >
                      Request return review for this order
                    </button>
                  )}
                  <Row
                    title="Discuss this exact record with Chuck"
                    onClick={() =>
                      flow.push(
                        featureScreen("AL-293", {
                          ...ctx,
                          objectId: o.id,
                          sourceId: o.id,
                        }),
                      )
                    }
                  />
                </section>
              ))}
            <Field
              label="Return or support reason"
              value={draft.text}
              type="textarea"
              onChange={(v) => set("text", v)}
            />
          </>
        ) : (
          <>
            <Field
              label="Your request"
              value={draft.text}
              type="textarea"
              onChange={(v) => set("text", v)}
            />
            <button
              className="primary"
              disabled={!draft.text.trim()}
              onClick={() =>
                save("service", draft.section, {
                  text: draft.text,
                  status: "awaiting-venue-response",
                  priceStatus: "Not set",
                })
              }
            >
              Prepare request for this venue
            </button>
            <Row
              title="Choose a meeting or session time"
              onClick={() =>
                flow.push(
                  featureScreen("AL-297", { ...ctx, purpose: draft.section }),
                )
              }
            />
            <Row
              title="View this venue’s community events"
              onClick={() => flow.push(featureScreen("AL-305", ctx))}
            />
          </>
        )}
        <ActionFeedback result={feedback} />
        {draft.section !== "Overview" && (
          <Row
            title="All services at this venue"
            onClick={() => section("Overview")}
          />
        )}
        <Row
          title="Back to this Venue Spot"
          onClick={() =>
            returnToScreen(flow,featureScreen("AL-035", { venueId: venue.id }))
          }
        />
        <NextActions featureId="AL-248" context={ctx} />
      </div>
    </MobileScroll>
  );
}

function ContentPreview({ post }: { post: NostrPost }) {
  const flow = useFlow();
  const { world,run } = useProduct();
  const [feedback,setFeedback]=useState<ActionResult|null>(null);
  useStoryExpiry(world, post);
  if (!mayRead(world, post)) return null;
  return (
    <article className="social-post">
      <div className="social-post-meta">
        <span>
          {post.type === "article"
            ? "Article"
            : post.type === "image"
              ? "Photos"
              : post.type === "live"
                ? "Replay"
                : post.type === "note"
                  ? "Post"
                  : post.type[0].toUpperCase() + post.type.slice(1)}
        </span>
        <time>
          {new Date(post.createdAt).toLocaleDateString("en-GB", {
            day: "numeric",
            month: "short",
          })}
        </time>
      </div>
      <button
        className="social-original"
        aria-label={`Read ${post.title}`}
        onClick={() => flow.push(originalScreen(post.id))}
      >
        {post.type !== "note" && <h2>{post.title}</h2>}
        <p>
          {post.type === "article" ? post.text.split("\n\n")[0] : post.text}
        </p>
        {post.protected ? <PaidMediaCover/> : post.image && !postMedia(post).length && (
          <img
            className="social-original-image"
            src={asset(post.image)}
            alt={post.alt || post.title}
          />
        )}{" "}
        {post.protected && (
          <span className="social-access">
            <ShieldCheck size={15} />
            Paid content · preview
          </span>
        )}
      </button>
      {postMedia(post).length ? (
        <PublishingMediaGallery media={postMedia(post)} />
      ) : null}
      <CreatorContentGate post={post}/>
      <VenueOfferCard post={post} />
      <PostVenueTag post={post} />
      {post.actions
        ?.filter((a) =>
          ["AL-305", "AL-297", "AL-141", "AL-095", "AL-097", "AL-099"].includes(
            a.featureId,
          ),
        )
        .map((action) => (
          <button
            className="secondary"
            key={action.label}
            onClick={() =>
              flow.push(
                featureScreen(action.featureId, {
                  venueId: post.venueId,
                  sourceId: post.id,
                  objectId: action.objectId,
                  relayId: post.venueId
                    ? `place-relay:${post.venueId}`
                    : undefined,
                }),
              )
            }
          >
            {action.label}
          </button>
        ))}
      <div className="social-post-actions" role="group" aria-label={`Actions for ${post.title}`}>
        <IconButton label={`Reply to ${post.title}`} onClick={()=>flow.push(editorScreen(post.id))}><ChatCircle size={22}/></IconButton>
        <IconButton label={`Give Props for ${post.title}`} onClick={()=>{const campaign=awardPostCampaign(world,post);if(campaign)flow.push(awardScreen({page:'campaign',id:campaign.id,sourcePostId:post.id,contestId:awardPostContestId(world,post)}));else flow.push({id:`props-original-${post.id}`,render:()=> <OriginalContent id={post.id} initialAction="Props"/>});}}><Lightning size={22}/></IconButton>
        <button type="button" className="icon-button" aria-pressed={post.liked} aria-label={`Like ${post.title}`} onClick={()=>setFeedback(run('nostr.interact',{action:'Like'},{featureId:'AL-109',postId:post.id}))}><Heart size={22} weight={post.liked?'fill':'regular'}/></button>
        <IconButton label={`Repost ${post.title}`} onClick={()=>flow.push({id:`repost-original-${post.id}`,render:()=> <OriginalContent id={post.id} initialAction="Repost"/>})}><Repeat size={22}/></IconButton>
        <button type="button" className="icon-button" aria-pressed={post.saved} aria-label={`Save ${post.title}`} onClick={()=>setFeedback(run('nostr.interact',{action:'Bookmark'},{featureId:'AL-109',postId:post.id}))}><BookmarkSimple size={22} weight={post.saved?'fill':'regular'}/></button>
      </div>{interactionRecords(world,post.id).length>0&&<button className="quiet" onClick={()=>flow.push(originalScreen(post.id))}>Review your public action</button>}<ActionFeedback result={feedback}/>
    </article>
  );
}
const operatorSetupScreen = () =>
  screen("operator-setup", "Join CRAYS as a Spot", () => <OperatorSetup />);
const venueOwnerScreen=(scopeId:string,page:'overview'|'finance'|'bookings'|'orders'='overview')=>screen(`venue-owner-${scopeId}-${page}`,page==='finance'?'Spot finances':'Manage your Spot',()=> <VenueOwnerEntry scopeId={scopeId} page={page}/>);
function VenueOwnerEntry({scopeId,page}:{scopeId:string;page:'overview'|'finance'|'bookings'|'orders'}){const {world}=useProduct();const flow=useFlow();const setup=world.objects.find(o=>o.id===scopeId&&o.kind==='venue-setup'&&o.owner===world.owner);const venueId=String(setup?.venueId||'');return <VenueOwnerWorkspace world={world} scopeId={scopeId} page={page} asset={asset} onSetup={()=>flow.push(venueSetupScreen(scopeId))} onMerchant={()=>flow.push(merchantAcceptanceScreen(scopeId))} onCatalogue={()=>flow.push(venueCatalogueScreen(scopeId))} onBookings={()=>flow.push(venueOwnerScreen(scopeId,'bookings'))} onOrders={()=>flow.push(venueOwnerScreen(scopeId,'orders'))} onFinance={()=>flow.push(venueOwnerScreen(scopeId,'finance'))} onPublic={()=>flow.push(placeScreen(venueId))} onSignIn={()=>flow.push(featureScreen('AL-003'))}/>;}
const merchantAcceptanceScreen=(scopeId:string)=>screen(`merchant-acceptance-${scopeId}`,"Guest payments",()=> <MerchantAcceptanceEntry scopeId={scopeId}/>);
function MerchantAcceptanceEntry({scopeId}:{scopeId:string}){const {world,run}=useProduct();const flow=useFlow();return <MerchantAcceptanceWorkspace key={`${world.owner}:${scopeId}`} world={world} run={run} scopeId={scopeId} onSetup={()=>flow.push(venueSetupScreen(scopeId))}/>;}
const venueSetupScreen = (setupId = "") => setupId
