const nostrSettingsScreen = (tab = "Identity") => webNostrScreen('root','',tab);
const webNostrScreen=(mode:WebNostrMode,sourceId='',tab='Identity',backLabel='Back')=>ownSpotChild({id:`web-nostr:${mode}:${sourceId||tab}`,render:()=> <NostrPanel mode={mode} sourceId={sourceId} tab={tab} backLabel={backLabel}/>});

const webClosureScreen=(mode:WebClosureMode='overview',sourceId:ClosureSource='contracts')=>ownSpotChild({id:'web-closure:'+mode+':'+sourceId,render:()=> <WebClosurePanel mode={mode} sourceId={sourceId}/>});
function WebClosurePanel({mode,sourceId}:{mode:WebClosureMode;sourceId:ClosureSource}){const {world}=useProduct();return <WebClosureEntry key={world.owner+':'+mode+':'+sourceId} mode={mode} sourceId={sourceId}/>;}
function WebClosureEntry({mode,sourceId}:{mode:WebClosureMode;sourceId:ClosureSource}){
 const {world,run}=useProduct(),{getState}=useStore(),flow=useFlow(),owner=world.owner;
 const {draft,set}=useOwnedFeatureDraft('control:support:'+(mode==='signout'?'AL-132':'AL-131'),{closureId:'',closureNote:'',closureRequestId:'',closureSamples:'No',closureWithdraw:'No'});
 const own=()=>{const w=getState().world;if(!w.identity.signedIn||w.owner!==owner)throw Error('Review your own signed-in account.');return w;};
 const open=(source:ClosureSource,ref?:string)=>{const world=own(),push=(target:FlowScreen)=>flow.push(ownSpotChild(target));if(ref&&!closureItems(world).items.some(i=>i.ref===ref&&i.source===source))throw Error('Review the exact original source item. No other source was opened.');
 if(ref?.startsWith("object:")){const objectId=ref.slice(7),original=world.objects.find(o=>o.owner===world.owner&&o.id===objectId);if(original&&world.objects.filter(o=>o.id===objectId).length===1){if(original.kind==="fitness-coaching-evidence-preview"){push(coachingEvidenceScreen("detail",objectId));return;}if(original.kind==="fitness-coaching-preview"){push(fitnessCoachingScreen("detail",objectId));return;}if(original.kind==="fitness-challenge-preview"){push(fitnessChallengeScreen("detail",objectId));return;}if(original.kind==="fitness-recognition-preview"){push(fitnessChallengeScreen("detail",String(original.participationId)));return;}if(original.kind==="fitness-media-preview"){push(fitnessMediaScreen("detail",objectId));return;}if(["fitness-goal-preview","fitness-measurement-preview"].includes(String(original.kind))){push(fitnessProgressScreen(original.kind==="fitness-goal-preview"?"goal":"measurement",objectId));return;}if(original.kind==="agent-task"){push(taskScreen(objectId));return;}if(original.kind==="space-membership-preview"){push(spaceMembershipScreen(objectId));return;}if(original.kind==="crays-plan-contract"){push(craysContractScreen(objectId));return;}if(original.kind==="ecosystem-invoice-preview"){push(ecosystemReceiptsScreen(String(original.membershipId||"")));return;}if(["permission","delegation"].includes(String(original.kind))){push(privacyCenterScreen(objectId));return;}if(original.kind==="device"){push(deviceRecoveryScreen("device",objectId));return;}}}
    if(ref?.startsWith("space:")){const venueId=ref.slice(6);if(world.venues.filter(v=>v.id===venueId).length===1){push(featureScreen("AL-035",{venueId}));return;}}
    if(ref?.startsWith("wallet:")||ref?.startsWith("payment:")){push(featureScreen("W01"));return;}
    const destinations={contracts:()=>screen("closure-commerce-review","Orders & bookings",()=> <CommerceExperience/>),tasks:tasksScreen,access:()=>controlScreen("privacy"),data:()=>controlScreen("privacy"),receipts:ecosystemReceiptsScreen,nostr:nostrSettingsScreen};push(destinations[source]());
 };
 return <WebAccountClosure mode={mode} sourceId={sourceId} world={world} getWorld={()=>getState().world} draft={draft} set={set} photo={asset} onBack={()=>flow.pop()} onGroup={source=>{own();flow.push(webClosureScreen('source',source));}} onResults={()=>{own();flow.push(webClosureScreen('results'));}} onSource={open} run={(op,data,ctx)=>{try{own();return run(op,data,{...ctx,personId:owner});}catch(e){return {ok:false,message:e instanceof Error?e.message:String(e),objectId:''} as ActionResult;}}}/>;
}

