function WebMemoryPanel({mode,recordId}:{mode:WebMemoryMode;recordId:string}){const {world}=useProduct();return <WebMemoryEntry key={world.owner+':'+mode+':'+recordId} mode={mode} recordId={recordId}/>;}
function WebMemoryEntry({mode,recordId}:{mode:WebMemoryMode;recordId:string}){const {world,run}=useProduct();const {getState}=useStore();const flow=useFlow(),owner=world.owner,source=ownMemory(world).find(o=>o.id===recordId);let snapshot='';try{snapshot=recordId?memorySnapshot(world,recordId):'';}catch{}const {draft,set}=useOwnedFeatureDraft(mode==='overview'?'control:memory:UX-CONTROL':`web-memory:correct:${recordId}`,{text:mode==='correct'?String(source?.name||''):'',purpose:mode==='correct'?String(source?.purpose||''):'This task only',...(mode==='correct'?{sourceSnapshot:snapshot}:{})});const own=()=>{const w=getState().world;if(w.owner!==owner||!w.identity.signedIn)throw Error('Review your own signed-in memory.');return w;};return <WebMemoryWorkspace mode={mode} recordId={recordId} draft={draft} set={set} photo={asset} world={world} getWorld={()=>getState().world} onBack={()=>flow.pop()} onCorrect={id=>{own();flow.push(webMemoryScreen('correct',id));}} onNotes={id=>{const w=own();if(id&&(w.objects.filter(o=>o.id===id).length!==1||w.objects.filter(o=>o.id===id&&o.owner===owner&&o.kind==='personal-note').length!==1))throw Error('Review this original own note. No other note was selected.');flow.push(ownSpotChild(id?personalNotesScreen(id):libraryWorkspaceScreen('libraryPrivateNotes')));}} run={(op,data,ctx)=>{try{own();return run(op,data,{...ctx,personId:owner});}catch(e){return {ok:false,message:e instanceof Error?e.message:String(e),objectId:''} as ActionResult;}}}/>;}
