// Original Markdown stays unchanged; no HTML injection or AI rewriting.
// Rendering follows the react-markdown / remark-gfm maintainers' documented API.
function OriginalArticle({ text, displayedTitle }: { text: string; displayedTitle?: string }) {
  // Only suppress the duplicate leading display heading; retain the source text.
  const firstLineEnd = text.indexOf("\n");
  const firstLine = (firstLineEnd < 0 ? text : text.slice(0, firstLineEnd)).trim();
  const articleText = displayedTitle && firstLine === `# ${displayedTitle}`
    ? (firstLineEnd < 0 ? "" : text.slice(firstLineEnd + 1).replace(/^\s*\n/, ""))
    : text;
  const flow = useFlow();
  const { world } = useProduct();
  return (
    <div className="original-article">
      <Markdown
        remarkPlugins={[remarkGfm]}
        urlTransform={(url) =>
          url.startsWith("nostr:") ? url : defaultUrlTransform(url)
        }
        components={{
          a: ({ href, children }) =>
            href?.startsWith("nostr:") ? (
              <button
                className="article-event-link"
                onClick={() => {
                  const id = href.slice(6);
                  if (world.posts.some((p) => p.id === id && mayRead(world, p)))
                    flow.push(originalScreen(id));
                }}
              >
                {children}
              </button>
            ) : (
              <a href={href} target="_blank" rel="noopener noreferrer">
                {children}
              </a>
            ),
          img: ({ src, alt }) =>
            typeof src === "string" && src.startsWith("/assets/crays/") ? (
              <img src={src} alt={alt || ""} />
            ) : (
              <span className="source-caption">
                {alt || "Original image"} · external media not available in this
                preview
              </span>
            ),
          table: ({ children }) => (
            <Carousel ariaLabel="Original article table">
              <table>{children}</table>
            </Carousel>
          ),
        }}
      >
        {articleText}
      </Markdown>
    </div>
  );
}

