type ReviewedChuckInput={text:string;label:string;context?:DraftContext;snapshot?:string};
function useReviewedChuckHandoff(onConfirmed?:()=>void,openConversation?:()=>FlowScreen){
 const {state,setState,getState,getScopeRevision}=useStore(),flow=useFlow();
 const [pending,setPending]=useState<{owner:string;revision:number;before:string;context:string;preview:ReviewedChuckInput;build:(s:State)=>ReviewedChuckInput;opener:HTMLElement|null}|null>(null),[problem,setProblem]=useState('');
 const account=(s:State)=>s.world.identity.signedIn===true&&typeof s.world.owner==='string'&&!!s.world.owner.trim()&&s.world.owner===s.world.owner.trim();
 const prepare=(build:(s:State)=>ReviewedChuckInput)=>{try{const s=getState();if(!account(s))throw Error('Sign in to prepare your own Chuck draft.');if(typeof s.drafts.chuck!=='string')throw Error('Review your original unsent draft before replacing it.');const preview=build(s);if(typeof preview.text!=='string'||!preview.text.trim())throw Error('Write the draft you want to review.');setProblem('');setPending({owner:s.world.owner,revision:getScopeRevision(),before:s.drafts.chuck,context:JSON.stringify(s.context.chuck||null),preview,build,opener:document.activeElement as HTMLElement});}catch(e){setProblem(e instanceof Error?e.message:'Reopen this draft.');}};
 const current=!!pending&&account(state)&&state.world.owner===pending.owner&&getScopeRevision()===pending.revision;
 const restore=()=>{const n=pending?.opener;if(n?.isConnected)n.focus({preventScroll:true});};
 const confirm=(replace:boolean)=>{if(!pending)return;try{let saved=false,reason='The account, source or unsent text changed. Cancel and review it again.';setState(s=>{try{if(!account(s)||s.world.owner!==pending.owner||getScopeRevision()!==pending.revision||s.drafts.chuck!==pending.before||JSON.stringify(s.context.chuck||null)!==pending.context||JSON.stringify(pending.build(s))!==JSON.stringify(pending.preview))return s;if(pending.before.trim()&&pending.before!==pending.preview.text&&!replace)return s;saved=true;return {...s,drafts:{...s.drafts,chuck:pending.preview.text},context:{...s.context,chuck:pending.preview.context}};}catch(e){reason=e instanceof Error?e.message:reason;return s;}});if(!saved)throw Error(reason);setPending(null);setProblem('');onConfirmed?.();flow.push(openConversation?.()||chatScreen('chuck','',true));}catch(e){setProblem(e instanceof Error?e.message:'Review the original draft again.');}};
 return {prepare,problem,review:pending?<WebChuckDraftReview key={pending.owner+pending.revision+pending.preview.text} open={current} current={pending.before} next={pending.preview.text} source={pending.preview.label} photo={state.world.profiles[state.world.owner]?.photo?asset(state.world.profiles[state.world.owner].photo):''} name={state.world.profiles[state.world.owner]?.name||'Your account'} error={problem} onCancel={()=>{restore();setPending(null);setProblem('');}} onRestoreFocus={restore} onConfirm={confirm}/>:null};
}
function WebActivityPlansEntry(){const {state,setState}=useStore(),flow=useFlow();const {draft,set}=useFeatureDraft('web-activity-plans',{selected:''});const [error,setError]=useState('');const handoff=useReviewedChuckHandoff();
 const open=(plan:PlanView)=>{if(plan.ref.origin==='travel'){const task=personalTasks(state.world,state.tasks).find(t=>t.origin==='travel'&&t.id===plan.ref.id);if(task)openPersonalTask(flow,task,state.world);}else flow.push(planScreen(plan.ref.id));};
 const prep=(plan:PlanView,version:number,action:PrepAction)=>{try{setState(s=>({...s,world:updatePlanPreparation(s.world,s.tasks,plan.ref,version,action)}));setError('');return true;}catch(e){setError(e instanceof Error?e.message:'Reopen this preparation.');return false;}};
 return <><WebActivityPlans world={state.world} legacy={state.tasks} selected={draft.selected} onSelected={key=>set('selected',key)} onOpen={open} onEdit={plan=>flow.push({id:'web-personal-plan-editor-'+(plan?.ref.id||'new'),title:'Your plan',render:()=> <WebPersonalPlanEntry planId={plan?.ref.id}/>})} onPrep={prep} onTask={id=>flow.push(manualTaskScreen(id))} onChuck={plan=>handoff.prepare(s=>{const original=resolveOwnPlan(s.world,s.tasks,plan.ref);return {text:'Help me prepare my plan “'+original.name+'”. Dates: '+(original.date||'not chosen')+'. Review proposals with me before any external action. My private preparation notes and files are not included.',context:{sourceId:original.ref.id,featureId:'AL-297'},label:original.name,snapshot:JSON.stringify(original.record)};})} onUpdates={()=>flow.push(screen('activity-updates','Updates',()=> <ActivityUpdates/>))} error={error||handoff.problem}/>{handoff.review}</>;
}
