const webHelpScreen=(mode:WebHelpMode='root',item='',kind:SupportKind='help',context:Partial<ActionContext>={},featureId='AL-126')=>ownSpotChild({id:'web-help:'+mode+':'+item+':'+kind+':'+featureId,render:()=> <WebHelpPanel mode={mode} item={item} kind={kind} context={context} featureId={featureId}/>});
