function WebHelpEntry(p:{mode:WebHelpMode;item:string;kind:SupportKind;context:Partial<ActionContext>;featureId:string}){
 const {world,run}=useProduct(),{getState}=useStore(),flow=useFlow(),owner=world.owner;
 const context:Partial<SupportContext>={};for(const k of ['objectId','sourceId','postId','venueId','productId','purpose'] as const){if(p.context[k]!==undefined&&!(k==='sourceId'&&['AL-129','AL-130'].includes(String(p.context[k]))))context[k]=p.context[k];}
 const extra=p.context as Record<string,unknown>;const scope=[typeof extra.purpose==='string'?extra.purpose:'',typeof extra.productId==='string'&&!extra.purpose?'Question about the selected item':'',p.context.sourceId==='AL-129'?'Terms of use':p.context.sourceId==='AL-130'?'Privacy information':''].filter(Boolean).join(' · ');
 const formFeature=p.item==='legacy-support-history'?'AL-206':p.featureId==='AL-300'&&p.kind==='feedback'?'AL-300':p.kind==='problem'?'AL-127':p.kind==='feedback'?'AL-128':'AL-126';
 const key=p.mode==='form'?`control:support:${formFeature}${Object.keys(context).length?':'+JSON.stringify(context):''}${scope?':'+scope:''}`:`web-help:${p.mode}:${p.item}`;
 const {draft:storedDraft,set}=useOwnedFeatureDraft(key,{text:'',source:scope,code:'',query:''});
 const draft=Object.fromEntries(Object.entries(storedDraft&&typeof storedDraft==='object'&&!Array.isArray(storedDraft)?storedDraft:{}).filter(([,v])=>typeof v==='string')) as Record<string,string>;
 const own=()=>{const w=getState().world;if(w.owner!==owner||!w.identity.signedIn||typeof w.owner!=='string'||!w.owner.trim()||w.owner!==w.owner.trim())throw Error('Sign in to your own account before continuing.');return w;};
 const open=(mode:WebHelpMode,item='',kind:SupportKind='help')=>flow.push(webHelpScreen(mode,item,kind,item==='legacy-support-history'?{}:p.context,item==='legacy-support-history'?'AL-206':p.featureId));
 const action=(destination:string)=>{own();if(destination==='support-report'){open('form','','problem');return;}const ids:Record<string,string>={wallets:'W01',memberships:'AL-179',notifications:'AL-123'};
 const direct:Record<string,()=>FlowScreen>={
 props:awardScreen,
 vifs:()=>({id:'help-vifs',render:()=> <WebVifsEntry/>}),
 chuck:()=>({id:'help-chuck',render:()=> <WebPersonalChuckEntry/>}),
 connect:()=>({id:'help-connect',render:()=> <WebSpotsConnectEntry/>}),
 'spots-discover':()=>({id:'help-spots-discover',render:()=> <WebSpotsDiscoverEntry/>}),
 spots:()=>({id:'help-spots',render:()=> <WebSpotsDiscoverEntry/>}),
 profile:()=>({id:'help-profile',render:()=> <WebAccountProfileEntry/>}),
 feed:()=>({id:'help-feed',render:()=> <NostrBrowser web/>}),
 'activity-commerce':()=>({id:'help-commerce',render:()=> <WebCommerceEntry/>}),
 'activity-plans':()=>({id:'help-plans',render:()=> <WebActivityPlansEntry/>}),
 'activity-travel':()=>({id:'help-travel',render:()=> <WebTravelMapEntry/>}),
 'activity-tasks':tasksScreen,
 wave:()=>waveScreen('Back to Help centre'),library:libraryScreen,closure:webClosureScreen,memory:webMemoryScreen,
 nostr:nostrSettingsScreen,hosting:()=>webNostrScreen('root','','Media','Back to Help centre'),
 security:()=>accountProtectionScreen('security'),privacy:privacyCenterScreen,
 visibility:affiliationSettingsScreen,devices:()=>deviceRecoveryScreen('overview'),editor:editorScreen};
 const push=(target:FlowScreen)=>flow.push(ownSpotChild({...target,render:state=><div className="wh-destination"><button className="wap-back wh-return" onClick={()=>flow.pop()}><CaretLeft size={22}/>Back to Help</button><div className="wh-destination-body">{target.render(state)}</div></div>}));
 if(direct[destination]){push(direct[destination]());return;}
 if(ids[destination]){push(featureScreen(ids[destination]));return;}
 if(destination==='legal'){open('legal','terms');return;}
 throw Error('This original destination needs review.');
 };
 return <WebHelpWorkspace {...p} photo={asset} context={context} world={world} getWorld={()=>getState().world} draft={draft} set={set} onBack={()=>flow.pop()} onOpen={open} onAction={action} run={(op,data,ctx)=>{try{own();return run(op,data,{...ctx,featureId:p.featureId,personId:owner});}catch(e){return {ok:false,message:e instanceof Error?e.message:String(e),objectId:''} as ActionResult;}}}/>;
}

