function PublicNostrComposerContent(){
 const {draft,set}=useOwnedFeatureDraft('public-nostr-compose',{format:'note',text:'',title:'',summary:'',identifier:'',media:'[]',warning:'',shortVideo:'No'});
 const [preview,setPreview]=useState<PublicPublicationDraft|null>(null),[problem,setProblem]=useState('');
 const flow=useFlow(),handoff=useReviewedChuckHandoff();
 type MediaDraft={url:string;mimeType:string;alt:string};
 let media:MediaDraft[]=[];try{const value=JSON.parse(draft.media||'[]');if(Array.isArray(value)&&value.length<=16)media=value;}catch{}
 const mimes=['image/jpeg','image/png','image/webp','image/avif','image/gif','image/apng','video/mp4','video/webm','video/quicktime','audio/mpeg','audio/mp4','audio/ogg','audio/wav','audio/flac'];
 const setMedia=(value:MediaDraft[])=>set('media',JSON.stringify(value));
 const review=()=>{
  try{
   const identifier=draft.identifier||crypto.randomUUID();
   const publication=snapshotPublicPublicationDraft({format:draft.format,text:draft.text,title:draft.title,...(draft.format==='article'?{identifier,summary:draft.summary}:{}),...(draft.format==='video'?{shortVideo:draft.shortVideo==='Yes'}:{}),media:media.map(item=>({url:item.url,mimeType:item.mimeType,alt:item.alt})),...(draft.warning?{warning:draft.warning}:{}),audience:'Public',access:'Free'});
   if(draft.format==='article'&&!draft.identifier)set('identifier',identifier);
   setProblem('');setPreview(publication);
  }catch{setProblem('Check your text, title and media links. Articles need text; photo and video posts need a title and matching media. Only public HTTPS links can be shared here.');}
 };
 return <MobileScroll><div className="detail-content legacy-post-composer public-nostr-composer"><WebFieldGroup id="PublicNostrComposer" className="public-composer-fields">
  <h1>Create a public post</h1>
  <p>Write your own original, add hosted media and review everything before sharing.</p>
  {preview?<LivePublicNostrDraftReview publication={preview} onClose={()=>setPreview(null)}/>:<>
   <Field label="Format" value={draft.format} options={['note','article','image','video','audio']} optionLabels={{note:'Text post',article:'Article',image:'Photo gallery',video:'Video',audio:'Audio'}} onChange={value=>set('format',value)}/>
   <Field label="Title" value={draft.title} onChange={value=>set('title',value)}/>
   <p className="source-caption">Live broadcasts, polls and documents are not connected to public publishing yet.</p>
   <Field label="Your original text" type="textarea" value={draft.text} onChange={value=>set('text',value)} placeholder="What would you like to share?"/>
   {draft.format==='article'&&<Field label="Article summary" value={draft.summary} onChange={value=>set('summary',value)}/>}
   {draft.format==='video'&&<Field label="Short video / reel" value={draft.shortVideo} options={['No','Yes']} onChange={value=>set('shortVideo',value)}/>}
   <section aria-label="Hosted media"><h2>Your media</h2><p className="source-caption">Add links to files you have permission to share. File upload is not connected yet.</p>
    {media.map((item,index)=><fieldset key={index} className="public-draft-media"><legend>Media {index+1}</legend>
     <Field label={`Media ${index+1} URL`} value={item.url} placeholder="https://…" onChange={url=>setMedia(media.map((entry,i)=>i===index?{...entry,url}:entry))}/>
     <Field label={`Media ${index+1} type`} value={item.mimeType} options={mimes} onChange={mimeType=>setMedia(media.map((entry,i)=>i===index?{...entry,mimeType}:entry))}/>
     <Field label={`Media ${index+1} description`} value={item.alt} onChange={alt=>setMedia(media.map((entry,i)=>i===index?{...entry,alt}:entry))}/>
     <button className="text-action" onClick={()=>setMedia(media.filter((_,i)=>i!==index))}>Remove media {index+1}</button>
    </fieldset>)}
    <button className="secondary" disabled={media.length>=16} onClick={()=>setMedia([...media,{url:'',mimeType:draft.format==='video'?'video/mp4':draft.format==='audio'?'audio/mpeg':'image/jpeg',alt:''}])}>Add hosted media</button>
   </section>
   <Field label="Content warning (optional)" value={draft.warning} onChange={value=>set('warning',value)}/>
   <section aria-label="Audience and access"><h2>Audience &amp; access</h2><p>Public · Free to read</p><p className="source-caption">Community, on-site, private-group and paid publishing require their own access checks and are not connected here. Only public/free publishing is supported here. Share only content and media you have permission to make public.</p></section>
   <div className="public-action-review-controls"><button className="primary" onClick={review}>Preview public post</button><button className="secondary" onClick={()=>handoff.prepare(()=>({text:`Help me edit this draft without publishing it:\n\n${draft.title}\n\n${draft.text}`,label:'Your public draft'}))}>Ask Chuck for help</button><button className="secondary" disabled title="Scheduling requires a connected publishing account">Schedule</button></div>
  </>}
  {problem&&<p role="alert">{problem}</p>}
  <button className="text-action" onClick={()=>flow.pop()}>Back to feed</button>
  {handoff.problem&&!handoff.review&&<p role="alert">{handoff.problem}</p>}{handoff.review}
 </WebFieldGroup></div></MobileScroll>;
}
